window.CSAE=window.CSAE||{};window.CSAE.laboratory=[{"week":1,"title":"HTML warm-up; Campus Notices page (HTML only)","focus":"Set up your tools, build a semantic page and a notice form, validate the markup","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Set up VS Code, Git and Developer Tools. Then build a semantic HTML page for the Campus Notices Board, with no styling, and add a notice-submission form with labelled inputs. Finish by validating the markup.",false]],[["Deliverable. ",true],["Lab 1 output: a folder campus-notices with index.html (no CSS yet) that passes the W3C Markup Validation Service with no errors, and a screenshot of the validator result.",false]]]},{"k":"callout","t":"Start from this skeleton. There is no stylesheet yet, because the styling comes in Week 2:"},{"k":"code","t":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Campus Notices</title>\n</head>\n<body>\n  <header>\n    <h1>Campus Notices</h1>\n  </header>\n  <main>\n    <article class=\"notice\">\n      <h2>Library hours extended</h2>\n      <p>The library stays open until 9 PM during midterm week.</p>\n    </article>\n  </main>\n  <footer>\n    <p>College of Computer Science, DMMMSU-SLUC</p>\n  </footer>\n</body>\n</html>","lang":"xml"}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: HTML warm-up","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-html-warm-up"},{"kind":"step","title":"Set up your tools","tag":"STEP 1","step":1,"blocks":[{"k":"list","items":[[["Install VS Code and Git if they are not on your computer yet. Use Chrome, Edge or Firefox as your browser.",false]],[["Open VS Code, then choose Terminal, then New Terminal.",false]],[["Check that Git works with the first command below. Then tell Git who you are with the other two, using your own name and email.",false]]]},{"k":"code","t":"git --version\ngit config --global user.name \"Your Name\"\ngit config --global user.email \"you@example.com\"","lang":"bash"},{"k":"list","items":[[["In your browser, press F12 to open Developer Tools. Find the Elements tab and the Network tab. You will use both in this lab.",false]]]}],"extra":["You should see a line that starts with git version, and a Developer Tools panel with an Elements tab and a Network tab."],"id":"set-up-your-tools"},{"kind":"step","title":"Create the project","tag":"STEP 2","step":2,"blocks":[{"k":"list","items":[[["Make a new folder called campus-notices on your computer.",false]],[["Open VS Code, choose File, then Open Folder, and pick it.",false]],[["Use the New File button in the sidebar to create index.html. You will add styles.css next week.",false]]]}],"extra":["You should see index.html listed in the Explorer."],"id":"create-the-project"},{"kind":"step","title":"Paste the skeleton and open it","tag":"STEP 3","step":3,"blocks":[{"k":"list","items":[[["Copy the skeleton from the lab brief at the top of this page into index.html and save (Ctrl+S).",false]],[["Open the file in your browser (double-click it, or right-click it in VS Code and choose Open with Live Server if you have that extension).",false]]]}],"extra":["You should see the heading \"Campus Notices\", one notice and a footer, in the browser's plain default style."],"id":"paste-the-skeleton-and-open-it"},{"title":"Add two more notices","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Copy the whole <article class=\"notice\">...</article> block and paste it twice below the first one.",false]],[["Change the <h2> and <p> text in each copy to real campus news.",false]],[["Save and refresh.",false]]]}],"extra":["You should see three notices. If one is missing or looks odd, check that every opening tag has its closing tag."],"id":"add-two-more-notices"},{"title":"Make the HTML more meaningful","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Inside each notice, add a date and a category:",false]]]},{"k":"code","t":"<article class=\"notice\">\n  <h2>Library hours extended</h2>\n  <p class=\"meta\">\n    <time datetime=\"2026-10-12\">12 October 2026</time> · <span class=\"tag\">Academic</span>\n  </p>\n  <p>The library stays open until 9 PM during midterm week.</p>\n</article>","lang":"xml"},{"k":"callout","t":"Save and refresh. You should see the date and category under each title. Semantic tags such as header, main, article, time and footer tell the browser and screen readers what each part is."}],"id":"make-the-html-more-meaningful"},{"kind":"step","title":"Add navigation, a list and a table","tag":"STEP 6","step":6,"blocks":[{"k":"list","items":[[["Inside the `header`, below the `h1`, add a `nav` with links that jump to parts of the page.",false]],[["Give the `main` element two `section` elements: one with `id=\"notices\"` that holds your articles, and one with `id=\"submit\"` for the form you will write in the next step.",false]],[["Add a list of categories and a small table of upcoming deadlines inside a third section.",false]]]},{"k":"code","t":"<nav aria-label=\"Main\">\n  <ul>\n    <li><a href=\"#notices\">Notices</a></li>\n    <li><a href=\"#deadlines\">Deadlines</a></li>\n    <li><a href=\"#submit\">Post a notice</a></li>\n  </ul>\n</nav>\n\n<section id=\"deadlines\">\n  <h2>Upcoming deadlines</h2>\n  <table>\n    <caption>Deadlines this month</caption>\n    <thead>\n      <tr><th scope=\"col\">Activity</th><th scope=\"col\">Date</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>Enrolment ends</td><td>20 January</td></tr>\n      <tr><td>Programming contest registration</td><td>25 January</td></tr>\n    </tbody>\n  </table>\n</section>","lang":"xml"},{"k":"p","t":"Click each link in the nav and check that the page scrolls to the right section. Add one more row to the table with a real deadline."}],"id":"add-navigation-a-list-and-a-table"},{"kind":"step","title":"Add the notice-submission form","tag":"STEP 7","step":7,"blocks":[{"k":"list","items":[[["Write the form inside the `section` with `id=\"submit\"`. Every input needs a `label` connected to it with `for` and `id`.",false]]]},{"k":"code","t":"<section id=\"submit\">\n  <h2>Post a notice</h2>\n  <form action=\"#\" method=\"post\">\n    <p>\n      <label for=\"title\">Title</label><br>\n      <input type=\"text\" id=\"title\" name=\"title\" required maxlength=\"100\">\n    </p>\n    <p>\n      <label for=\"category\">Category</label><br>\n      <select id=\"category\" name=\"category\">\n        <option value=\"academic\">Academic</option>\n        <option value=\"event\">Event</option>\n        <option value=\"general\">General</option>\n      </select>\n    </p>\n    <p>\n      <label for=\"date\">Date</label><br>\n      <input type=\"date\" id=\"date\" name=\"date\">\n    </p>\n    <p>\n      <label for=\"message\">Message</label><br>\n      <textarea id=\"message\" name=\"message\" rows=\"4\" required></textarea>\n    </p>\n    <p>\n      <label for=\"email\">Your email</label><br>\n      <input type=\"email\" id=\"email\" name=\"email\" required>\n    </p>\n    <button type=\"submit\">Post notice</button>\n  </form>\n</section>","lang":"xml"},{"k":"p","t":"Click the label \"Title\": the cursor should jump into the text box. Submit the form empty, and the browser should stop you and point at the first required field. Press Tab through the whole form to confirm that you can reach every field with the keyboard."}],"extra":["Nothing is sent anywhere yet. The form is just markup until you connect it to a server in later weeks."],"id":"add-the-notice-submission-form"},{"kind":"step","title":"Validate the markup","tag":"STEP 8","step":8,"blocks":[{"k":"list","items":[[["Open validator.w3.org in your browser and choose the \"Validate by File Upload\" tab.",false]],[["Upload index.html and click Check.",false]],[["Read the messages from the top. Fix the first error, save, and check again.",false]],[["Repeat until the result says \"Document checking completed. No errors or warnings to show.\"",false]]]},{"k":"p","t":"Common problems: a missing closing tag, a duplicate `id`, a `p` inside another `p`, an `img` with no `alt`, and a `section` with no heading."}],"extra":["Take a screenshot of the clean result for your deliverable."],"id":"validate-the-markup"},{"kind":"step","title":"Commit with Git and show your instructor","tag":"STEP 9","step":9,"blocks":[{"k":"code","t":"git init\ngit add index.html\ngit commit -m \"Add semantic Campus Notices page and notice form\"","lang":"bash"},{"k":"list","items":[[["Show your instructor the page in the browser, the validator screenshot and the output of `git log --oneline`.",false]]]}],"id":"commit-with-git-and-show-your-instructor"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["Git is installed and `git --version` shows a version number.",false]],[["The page has a header with a nav, a main area with at least three notices, a deadlines table and a footer.",false]],[["The notice form has labelled inputs of at least four different types, and every label is connected to its input.",false]],[["Every image, if you added any, has alt text. Headings are in order, with one `h1`.",false]],[["The W3C validator shows no errors, and you have the screenshot.",false]],[["You committed your work with Git.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a fieldset and legend around the category and date, add a second form for subscribing to notices by email, and mark the page's language and a short description with a `meta` tag. Validate again."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: HTML and CSS warm-up","path":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx"}],"pptx":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 1","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Set up a web development environment with VS Code, Git and browser Developer Tools.","Explain the structure of an HTML document.","Use semantic elements, links, images, lists and tables correctly.","Build accessible HTML forms and validate markup."],"topics":{"lecture":["Course orientation and Campus Notices Board overview","Web development tools: VS Code, Git and browser Developer Tools","HTML document structure, elements and attributes","Semantic elements, headings, links, images, lists and tables","Forms and input types; accessibility basics (alt text, labels)"],"laboratory":["Set up VS Code, Git and browser Developer Tools","Build a semantic HTML page for the Campus Notices Board (no styling)","Add a notice-submission form with labelled inputs and validate the markup"]},"methods":["Interactive lecture","Guided practice (HTML warm-up)","Flipped learning (pre-reading)","Peer code review"],"resources":["VS Code; Git; Chrome, Edge or Firefox with Developer Tools","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 1 materials","Mozilla Developer Network (n.d.), Learn web development: HTML guides","W3C (n.d.), HTML specification and Markup Validation Service"],"assessment":["Quiz 1: HTML structure, semantic elements and forms","Lab 1 output: semantic HTML page with form","Recitation: choose the right semantic element"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Web markup is the entry-point competency for every web and ICT career."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.c: Significantly increase access to information and communications technology.","link":"HTML is the open standard through which information reaches communities."}]}},{"week":2,"title":"Styling the Campus Notices page","focus":"External stylesheet, box model, typography and colour variables, debugging with the Styles panel","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Style your Week 1 page with an external stylesheet. Use the box model, typography and colour variables, and learn to debug conflicting rules with the Styles panel.",false]],[["Deliverable. ",true],["Lab 2 output: index.html linked to styles.css, a styled Campus Notices page that uses CSS variables, and a screenshot of the Styles panel showing a rule you overrode on purpose and then fixed.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: styling the Campus Notices page","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-styling-the-campus-notices-pa"},{"kind":"step","title":"Link an external stylesheet","tag":"STEP 1","step":1,"blocks":[{"k":"list","items":[[["In your campus-notices folder, create styles.css.",false]],[["In index.html, add this line inside the `head`, below the `title`:",false]]]},{"k":"code","t":"<link rel=\"stylesheet\" href=\"styles.css\">","lang":"xml"},{"k":"list","items":[[["Add one rule to styles.css, such as `body { background: #f4f7fa; }`, and refresh. The background should change.",false]]]}],"extra":["Open the Network tab and reload. styles.css should appear with status 200. Now misspell the file name in the link, reload, and watch a 404 row appear and the page lose its style. Fix the spelling again."],"id":"link-an-external-stylesheet"},{"kind":"step","title":"Define the colour variables and the base styles","tag":"STEP 2","step":2,"blocks":[{"k":"list","items":[[["Put these variables and base rules at the top of styles.css. Every colour on the page will come from the variables.",false]]]},{"k":"code","t":":root {\n  --brand: #1d4e89;\n  --brand-soft: #e0ecf8;\n  --surface: #ffffff;\n  --page: #f4f7fa;\n  --text: #1f2933;\n  --border: #d9e2ec;\n  --radius: 8px;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  font-family: system-ui, sans-serif;\n  font-size: 1rem;\n  line-height: 1.5;\n  margin: 0;\n  background: var(--page);\n  color: var(--text);\n}","lang":"css"},{"k":"p","t":"Save and refresh. The text should now use the system font with comfortable line spacing."}],"id":"define-the-colour-variables-and-the-base-styles"},{"kind":"step","title":"Style the header, the notices and the footer","tag":"STEP 3","step":3,"blocks":[{"k":"list","items":[[["Add these rules one block at a time, saving and refreshing after each, so you can see what each one does. Use only normal flow for now; layout comes next week.",false]]]},{"k":"code","t":"header {\n  background: var(--brand);\n  color: white;\n  padding: 16px 24px;\n}\n\nmain {\n  max-width: 720px;\n  margin: 24px auto;\n  padding: 0 16px;\n}\n\n.notice {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 16px;\n  margin-bottom: 16px;\n}\n\n.tag {\n  background: var(--brand-soft);\n  border-radius: 4px;\n  padding: 2px 8px;\n  font-size: 0.85rem;\n}\n\nfooter {\n  text-align: center;\n  padding: 16px;\n}","lang":"css"},{"k":"p","t":"You should see a blue header, a centred column and white cards with rounded corners. Each card has content, then padding, then a border, then margin around it. That is the box model."}],"id":"style-the-header-the-notices-and-the-footer"},{"kind":"step","title":"Style the links, the nav, the table and the form","tag":"STEP 4","step":4,"blocks":[{"k":"code","t":"nav ul { list-style: none; margin: 0; padding: 0; }\nnav li { display: inline-block; margin-right: 16px; }\nnav a { color: white; text-decoration: none; }\nnav a:hover { text-decoration: underline; }\n\ntable { border-collapse: collapse; width: 100%; background: var(--surface); }\nth, td { border: 1px solid var(--border); padding: 8px; text-align: left; }\nth { background: var(--brand-soft); }\n\ninput, select, textarea {\n  width: 100%;\n  padding: 8px;\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  font: inherit;\n}\ninput:focus, select:focus, textarea:focus { outline: 3px solid var(--brand); }\n\nbutton {\n  background: var(--brand);\n  color: white;\n  border: 0;\n  border-radius: var(--radius);\n  padding: 10px 20px;\n  font: inherit;\n  cursor: pointer;\n}\nbutton:hover { background: #163b69; }","lang":"css"},{"k":"p","t":"Press Tab to move through the form. The field that has focus must be clearly visible."}],"id":"style-the-links-the-nav-the-table-and-the-form"},{"kind":"step","title":"Inspect the box model","tag":"STEP 5","step":5,"blocks":[{"k":"list","items":[[["Right-click a notice card and choose Inspect.",false]],[["In the Styles panel, find the box diagram. Hover over each layer to see the content, padding, border and margin highlighted on the page.",false]],[["Change the padding of the card in the Styles panel and watch it update. Reload to discard the change.",false]],[["Write down the total width on screen of one card: content plus padding plus border.",false]]]}],"id":"inspect-the-box-model"},{"kind":"step","title":"Debug conflicting rules on purpose","tag":"STEP 6","step":6,"blocks":[{"k":"list","items":[[["Add this rule at the very bottom of styles.css:",false]]]},{"k":"code","t":"p { color: red; }","lang":"css"},{"k":"list","items":[[["Reload. Some text turns red, but the notice meta line does not change the way you expected.",false]],[["Inspect a paragraph. In the Styles panel, find which declarations are crossed out and which rule overrides them. Take a screenshot.",false]],[["Explain in a comment in styles.css why one rule won: was it specificity, order, or inheritance?",false]],[["Fix the problem by changing the selector, not by using `!important`. Then delete the experiment.",false]]]}],"extra":["A rule with a line through it lost the cascade. The rule above it in the list is the one that won."],"id":"debug-conflicting-rules-on-purpose"},{"kind":"step","title":"Commit your work","tag":"STEP 7","step":7,"blocks":[{"k":"code","t":"git add index.html styles.css\ngit commit -m \"Add external stylesheet with variables\"","lang":"bash"},{"k":"list","items":[[["Show your instructor the styled page and your Styles-panel screenshot.",false]]]}],"id":"commit-your-work"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["styles.css is linked from index.html, and the Network tab shows it loading with status 200.",false]],[["Every colour comes from a CSS variable defined on `:root`.",false]],[["The page uses `box-sizing: border-box`, padding, border, margin and `rem` units.",false]],[["The nav links, table, form fields and button are styled, and the form fields show a clear focus outline.",false]],[["You have a screenshot of the Styles panel showing a rule you overrode and fixed without `!important`.",false]],[["You committed your work.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a dark theme. Define a second set of variables inside `@media (prefers-color-scheme: dark)` that override the `:root` colours. Switch your computer's theme and confirm that the page changes with no JavaScript."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: HTML and CSS warm-up","path":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx"}],"pptx":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 2","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Write CSS rules using selectors, properties and values.","Explain the cascade, specificity and inheritance.","Apply the box model, colors, typography and backgrounds.","Debug styles using browser Developer Tools."],"topics":{"lecture":["Linking CSS: inline, internal and external stylesheets","Selectors, combinators, pseudo-classes and specificity","The cascade and inheritance","The box model: margin, border, padding, width and height","Colors, units, typography, backgrounds and CSS variables","Inspecting and debugging styles in DevTools"],"laboratory":["Style the Week 1 page with an external stylesheet","Use the box model, typography and color variables","Debug conflicting rules using the Styles panel"]},"methods":["Lecture with live coding","Predict-the-output activity (specificity)","Guided practice","Paired programming"],"resources":["VS Code; browser Developer Tools","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 2 materials","Mozilla Developer Network (n.d.), Learn web development: CSS guides","Duckett (2011), chapters on CSS fundamentals"],"assessment":["Quiz 2: selectors, cascade and the box model","Lab 2 output: styled Campus Notices page","Recitation: explain why a rule wins the cascade"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"CSS skills are expected of entry-level front-end and full-stack developers."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"Well-styled interfaces make locally built digital services usable."}]}},{"week":3,"title":"Responsive Campus Notices Board (static)","focus":"Flexbox and Grid layout, mobile-first media queries, device emulation","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Lay out the notices page with Flexbox and Grid, make it responsive with mobile-first media queries, test it at several screen sizes with device emulation, and submit the static page.",false]],[["Deliverable. ",true],["Lab 3 output: the responsive static Campus Notices Board (index.html and styles.css) that works from 320px to a wide desktop with no sideways scrolling, plus screenshots of three screen sizes and the layout practical.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: responsive static Campus Notices Board","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-responsive-static-campus-noti"},{"kind":"step","title":"Check the viewport tag and set a mobile-first base","tag":"STEP 1","step":1,"blocks":[{"k":"list","items":[[["Confirm that the `head` of index.html has `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">`.",false]],[["Press F12, then Ctrl+Shift+M, and choose a phone such as iPhone SE (320 to 375px wide). Reload.",false]],[["Fix anything that overflows sideways: make images `max-width: 100%`, and use `max-width` instead of fixed `width` on containers.",false]]]},{"k":"code","t":"img { max-width: 100%; height: auto; }\ntable { display: block; overflow-x: auto; } /* a wide table scrolls inside itself */","lang":"css"}],"extra":["The page should look good on a narrow screen before you write any media query. That is what mobile-first means."],"id":"check-the-viewport-tag-and-set-a-mobile-first-ba"},{"kind":"step","title":"Lay out the header with Flexbox","tag":"STEP 2","step":2,"blocks":[{"k":"list","items":[[["Make the header a flexible row that wraps on small screens. Replace the nav rules from last week with these.",false]]]},{"k":"code","t":"header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px 24px;\n}\n\nnav ul {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px 16px;\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}","lang":"css"},{"k":"p","t":"Resize the browser. The title and the menu should sit side by side when there is room, and wrap onto two lines when there is not."}],"id":"lay-out-the-header-with-flexbox"},{"kind":"step","title":"Lay out the notices with Grid","tag":"STEP 3","step":3,"blocks":[{"k":"list","items":[[["Wrap your notice articles in a `div` with `class=\"notices\"`, or give the section that holds them that class.",false]],[["Start with one column, then add columns as the screen grows.",false]]]},{"k":"code","t":"main {\n  max-width: 1100px;\n  margin: 24px auto;\n  padding: 0 16px;\n}\n\n.notices {\n  display: grid;\n  gap: 16px;\n  grid-template-columns: 1fr;      /* phone: one column */\n}\n\n.notice { margin-bottom: 0; }      /* the grid gap now handles the spacing */","lang":"css"},{"k":"p","t":"Add at least six notices so the grid has something to lay out. Copy and edit the articles you already have."}],"id":"lay-out-the-notices-with-grid"},{"kind":"step","title":"Add mobile-first media queries","tag":"STEP 4","step":4,"blocks":[{"k":"code","t":"@media (min-width: 600px) {\n  .notices { grid-template-columns: repeat(2, 1fr); }\n}\n\n@media (min-width: 960px) {\n  .notices { grid-template-columns: repeat(3, 1fr); }\n  header { padding: 24px 32px; }\n}","lang":"css"},{"k":"list","items":[[["Drag the width of the device toolbar slowly from 320px to 1200px.",false]],[["Watch the layout change from one column to two and then three, and find the widths where it changes.",false]]]}],"extra":["Every query uses `min-width`. Your base CSS is the phone layout, and each query only adds what a bigger screen needs."],"id":"add-mobile-first-media-queries"},{"kind":"step","title":"Add a sidebar with a Grid page layout","tag":"STEP 5","step":5,"blocks":[{"k":"list","items":[[["Give the whole page a header, a main area, an aside for the deadlines table, and a footer, using named grid areas on larger screens.",false]]]},{"k":"code","t":"body { display: grid; gap: 16px; }\n\n@media (min-width: 960px) {\n  body {\n    grid-template-columns: 1fr 300px;\n    grid-template-areas:\n      \"header header\"\n      \"main   aside\"\n      \"footer footer\";\n  }\n  header { grid-area: header; }\n  main   { grid-area: main; }\n  aside  { grid-area: aside; }\n  footer { grid-area: footer; }\n}","lang":"css"},{"k":"p","t":"Move the deadlines section into an `aside` element after `main`. On a phone, it should appear below the notices. On a desktop, it should appear as a sidebar to the right."}],"id":"add-a-sidebar-with-a-grid-page-layout"},{"kind":"step","title":"Test on several screen sizes","tag":"STEP 6","step":6,"blocks":[{"k":"list","items":[[["In the device toolbar, test a phone (375px), a tablet (768px) and a laptop (1280px). Also rotate the phone to landscape.",false]],[["At each size, check: no horizontal scrollbar, text is readable without zooming, tap targets are not tiny, and the nav is usable.",false]],[["Take one screenshot at each of the three sizes.",false]]]}],"id":"test-on-several-screen-sizes"},{"kind":"step","title":"Layout practical: reproduce a given layout","tag":"STEP 7","step":7,"blocks":[{"k":"list","items":[[["Create a separate file layout.html with its own CSS and no content except coloured boxes labelled A to F.",false]],[["Reproduce the layout your instructor shows you. Build it once with Flexbox and once with Grid.",false]],[["Write one sentence about which one was easier for this layout, and why.",false]]]}],"id":"layout-practical-reproduce-a-given-layout"},{"kind":"step","title":"Commit and submit the static page","tag":"STEP 8","step":8,"blocks":[{"k":"code","t":"git add .\ngit commit -m \"Make the Campus Notices Board responsive with Flexbox and Grid\"","lang":"bash"},{"k":"list","items":[[["Submit your folder as your instructor directs, with your three screenshots.",false]]]}],"id":"commit-and-submit-the-static-page"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The header uses Flexbox, and the notices and the page areas use Grid.",false]],[["The page is written mobile-first, with only `min-width` media queries.",false]],[["There is no horizontal scrolling at 320px, 768px or 1280px.",false]],[["You have three screenshots, one for each size.",false]],[["layout.html reproduces the given layout with Flexbox and with Grid.",false]],[["You committed your work.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Use `grid-template-columns: repeat(auto-fit, minmax(260px, 1fr))` to make the notices grid responsive with no media query at all. Explain in a comment how it works and when you would still need a media query."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: HTML and CSS warm-up","path":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx"}],"pptx":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 3","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Build page layouts using Flexbox and CSS Grid.","Create responsive designs with media queries and relative units.","Apply a mobile-first approach.","Complete a responsive static Campus Notices Board page."],"topics":{"lecture":["Display, positioning and normal flow","Flexbox: containers, items, alignment and wrapping","CSS Grid: tracks, areas and gaps","Responsive design: viewport meta, media queries and relative units","Mobile-first workflow; testing with device emulation"],"laboratory":["Lay out the notices page with Flexbox and Grid","Make the page responsive with media queries (mobile-first)","Test on multiple screen sizes using device emulation and submit the static page"]},"methods":["Lecture with live coding","Layout lab (Flexbox and Grid)","Project-based learning (Campus Notices Board)","Peer review"],"resources":["VS Code; browser Developer Tools (device emulation)","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 3 materials","Mozilla Developer Network (n.d.), CSS layout, Flexbox, Grid and responsive design guides","Duckett (2011), chapters on layout"],"assessment":["Lab 3 output: responsive static Campus Notices Board page","Layout practical: reproduce a given layout in Flexbox and Grid","Peer review rubric"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Responsive design is a baseline skill for web employment."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.c: Significantly increase access to information and communications technology.","link":"Mobile-friendly pages widen access to information and ICT."}]}},{"week":4,"title":"HTTP inspection; JavaScript and the DOM","focus":"Read a request and response in the Network tab, ES6 exercises, make the notices page interactive","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Inspect an HTTP request and response in the Network tab, practise modern JavaScript on small problems, then make the Notices page interactive with DOM events.",false]],[["Deliverable. ",true],["Lab 4 output: a text file http-trace.txt with your answers to the HTTP questions and a screenshot of the Network tab, plus a folder js-practice with index.html, main.js and notices.js that renders and filters a list of notices with no errors in the console.",false]]]},{"k":"callout","t":"Answer these three questions in http-trace.txt:"},{"k":"list","items":[[["What are the method, status code and Content-Type of the first request for https://example.com?",false]],[["What status code do you get for https://jsonplaceholder.typicode.com/posts/9999, and what does it mean?",false]],[["Why does a browser make several requests to show one page?",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: HTTP inspection and JavaScript","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-http-inspection-and-javascrip"},{"kind":"step","title":"Trace one page load in the Network tab","tag":"STEP 1","step":1,"blocks":[{"k":"list","items":[[["Open a new tab, press F12, and choose the Network tab. Keep it open.",false]],[["Visit https://example.com. You should see one or two rows appear.",false]],[["Click the first row. In the Headers panel, find the Request URL, the Request Method, the Status Code and the Content-Type of the response.",false]],[["Write these four values in http-trace.txt.",false]]]}],"extra":["Tick \"Disable cache\" so every reload makes real requests."],"id":"trace-one-page-load-in-the-network-tab"},{"kind":"step","title":"Read a request and a response in detail","tag":"STEP 2","step":2,"blocks":[{"k":"list","items":[[["Visit https://jsonplaceholder.typicode.com/posts/1. This is an API, so the response is JSON, not a web page.",false]],[["In the Network tab, click the request. Look at the Request Headers (Accept, User-Agent) and at the Response Headers (Content-Type, Cache-Control).",false]],[["Open the Response tab to see the body, and the Preview tab to see it as a tree.",false]],[["Compare the Content-Type with the one from example.com. Write one sentence on how they differ.",false]]]}],"id":"read-a-request-and-a-response-in-detail"},{"kind":"step","title":"Make a 404 on purpose","tag":"STEP 3","step":3,"blocks":[{"k":"list","items":[[["Visit https://jsonplaceholder.typicode.com/posts/9999. Find the status code of the request.",false]],[["Visit https://example.com/nothing-here. Compare the two answers.",false]],[["Open your own page from Week 3 and misspell the stylesheet name once more to see the 404 in the Network tab. Then fix it.",false]],[["Save a screenshot of the Network tab showing one 200 and one 404 together, and finish answering the three questions.",false]]]}],"id":"make-a-404-on-purpose"},{"title":"Create the project","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Make a folder js-practice with three files: index.html, main.js and notices.js.",false]],[["Put this in index.html:",false]]]},{"k":"code","t":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>JS Practice</title>\n  </head>\n  <body>","lang":"xml"},{"k":"code","t":"    <h1>Campus Notices</h1>\n    <input id=\"search\" placeholder=\"Search notices...\" />\n    <ul id=\"list\"></ul>\n    <script type=\"module\" src=\"main.js\"></script>\n  </body>\n</html>","lang":"xml"},{"k":"callout","t":"Modules do not load when you double-click the file. Open the page with the Live Server extension (right-click index.html, then Open with Live Server), or run npx serve in the folder. You should see the heading and the search box, and no red errors in the Console."}],"id":"create-the-project"},{"title":"Warm-up: arrow functions","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In main.js, rewrite these three function declarations as arrow functions with the same names:",false]]]},{"k":"code","t":"function double(n) { return n * 2; }\nfunction greet(name) { return \"Hello, \" + name; }\nfunction isLong(text) { return text.length > 20; }","lang":"javascript"},{"k":"callout","t":"Check yourself: double(4) should log 8, greet(\"Ana\") should log Hello, Ana, and isLong(\"short\") should log false. Compare with this answer:"},{"k":"code","t":"const double = (n) => n * 2;\nconst greet = (name) => `Hello, ${name}`;\nconst isLong = (text) => text.length > 20;","lang":"javascript"}],"id":"warm-up-arrow-functions"},{"title":"Array methods","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Start with this array of store items:",false]]]},{"k":"code","t":"const items = [\n  { name: \"Coffee sachet\", price: 8 },\n  { name: \"Biscuit\", price: 12 },\n  { name: \"Softdrink\", price: 25 },\n  { name: \"Candy\", price: 2 },\n];","lang":"javascript"},{"k":"callout","t":"Use map, filter and reduce to produce: (a) an array of the names, (b) the items under PHP 20, and (c) the total price. You should log [\"Coffee sachet\", \"Biscuit\", \"Softdrink\", \"Candy\"], then three items (all except Softdrink), then 47. Compare with:"},{"k":"code","t":"const names = items.map((item) => item.name);\nconst cheap = items.filter((item) => item.price < 20);\nconst total = items.reduce((sum, item) => sum + item.price, 0);","lang":"javascript"}],"id":"array-methods"},{"title":"Destructuring and spread","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Create an object and change one field without changing the original:",false]]]},{"k":"code","t":"const notice = { id: 1, title: \"Library hours\", pinned: false };\nconst { title } = notice;                         // destructuring: pull out one field\nconst pinnedNotice = { ...notice, pinned: true }; // spread: copy, then override\nconsole.log(notice, pinnedNotice);","lang":"javascript"},{"k":"callout","t":"You should see pinned: false in the first object and pinned: true in the second. That proves the original did not change."}],"id":"destructuring-and-spread"},{"title":"Modules","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["In notices.js, move the data and export it:",false]]]},{"k":"code","t":"export const notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM during midterm week.\" },\n  { id: 2, title: \"Enrollment reminder\", message: \"Last day to add or drop subjects is Friday.\" },\n  { id: 3, title: \"Programming contest\", message: \"Sign up at the CCS office by Monday.\" },\n  { id: 4, title: \"Wi-Fi maintenance\", message: \"The campus network is down Sunday morning.\" },\n];","lang":"javascript"},{"k":"callout","t":"In main.js, import it at the top with import { notices } from \"./notices.js\"; and run console.log(notices);. You should see the four notices in the Console. If you see an error that mentions CORS or file://, you opened the page without a server."}],"id":"modules"},{"title":"Render with the DOM","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["Add this to main.js:",false]]]},{"k":"code","t":"const list = document.querySelector(\"#list\");\n\nfunction render(items) {\n  list.innerHTML = \"\";               // clear the old list first\n  items.forEach((n) => {\n    const li = document.createElement(\"li\");\n    li.textContent = `${n.title}: ${n.message}`;\n    list.appendChild(li);\n  });\n}","lang":"javascript"},{"k":"code","t":"render(notices);","lang":"javascript"},{"k":"callout","t":"You should see four bullet points on the page."}],"id":"render-with-the-dom"},{"title":"Events: search as you type","tag":"STEP 10","kind":"step","step":10,"blocks":[{"k":"code","t":"const search = document.querySelector(\"#search\");\n\nsearch.addEventListener(\"input\", () => {\n  const text = search.value.toLowerCase();\n  const matches = notices.filter((n) => n.title.toLowerCase().includes(text));\n  render(matches);\n});","lang":"javascript"},{"k":"callout","t":"Type \"wi\" in the box. You should see only the Wi-Fi notice. Clear the box and all four come back."}],"id":"events-search-as-you-type"},{"title":"Clean up and show your instructor","tag":"STEP 11","kind":"step","step":11,"blocks":[{"k":"list","items":[[["Remove unused console.log lines and make sure the Console has no errors.",false]]]}],"id":"clean-up-and-show-your-instructor"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["http-trace.txt answers the three HTTP questions, and you have the Network-tab screenshot with a 200 and a 404.",false]],[["The three arrow functions, the array methods and the spread example all work.",false]],[["The data lives in notices.js and is imported into main.js.",false]],[["The list renders from the array, and the search box filters it as you type.",false]],[["The Console shows no errors.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Save the notices in localStorage so the list survives a page refresh. Remember that localStorage stores only strings."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: HTML and CSS warm-up","path":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx"},{"label":"Earlier deck: Modern JavaScript","path":"downloads/laboratory/Week_02_Laboratory_Modern_JavaScript.pptx"}],"pptx":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 4","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Describe the client-server model and the request-response cycle.","Read HTTP requests, responses, headers and status codes in the Network tab.","Write JavaScript using ES6+ syntax and modules.","Select and manipulate DOM elements and respond to events."],"topics":{"lecture":["Client-server model, URLs, DNS and the request-response cycle","HTTP methods, headers and status codes","Inspecting traffic with browser Developer Tools","ES6+: let/const, arrow functions, destructuring, template literals","Modules (import/export); DOM selection, events and manipulation"],"laboratory":["Inspect an HTTP request and response in the Network tab","Complete ES6 exercises","Make the Notices page interactive with DOM events"]},"methods":["Interactive lecture","Visual demonstration (DevTools Network tab)","Predict-the-output activity","Paired programming"],"resources":["VS Code; browser Developer Tools","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 4 materials","Fielding et al. (2022), RFC 9110 (selected sections on HTTP semantics)","Mozilla Developer Network (n.d.), HTTP and JavaScript guides","Haverbeke (2018), chapters on the DOM"],"assessment":["Quiz 3: HTTP, ES6 and the DOM","Lab 4 output: HTTP trace and interactive notices page","Recitation: trace what happens when a URL is opened"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Understanding how the web works and core JavaScript are entry-point competencies for web careers."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.c: Significantly increase access to information and communications technology.","link":"The web is the delivery channel through which access to ICT and information reaches communities."}]}},{"week":5,"title":"Fetching data; first Node program and package setup","focus":"Fetch from a public API with loading and error states, write Node scripts, set up npm and push to GitHub","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Read data from a public API and show it on a web page with loading and error messages. Then write and run a Node program, set it up as an npm project, and push it to GitHub.",false]],[["Deliverable. ",true],["Lab 5 output: (1) a page that fetches posts from https://jsonplaceholder.typicode.com/posts, shows them as cards, and handles loading and errors; (2) a project notices-cli with package.json, .gitignore and a program that can add and list notices; and (3) both projects pushed to GitHub. Submit the repository links on Google Classroom.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: fetch data, write Node programs, publish to GitHub","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-fetch-data-write-node-program"},{"title":"Try fetch in the Console","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Open any web page, press F12, choose Console, and type:",false]]]},{"k":"code","t":"fetch(\"https://jsonplaceholder.typicode.com/posts/1\")\n  .then((res) => res.json())\n  .then((data) => console.log(data));","lang":"javascript"},{"k":"callout","t":"You should see an object with userId, id, title and body. In the Network tab, find the request and note its status code (200)."}],"id":"try-fetch-in-the-console"},{"title":"Create the project","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Make a folder fetch-posts with index.html and app.js:",false]]]},{"k":"code","t":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Posts</title>\n  </head>\n  <body>\n    <h1>Posts</h1>\n    <input id=\"search\" placeholder=\"Search by title...\" />\n    <p id=\"status\"></p>\n    <div id=\"posts\"></div>","lang":"xml"},{"k":"code","t":"    <script src=\"app.js\"></script>\n  </body>\n</html>","lang":"xml"},{"k":"callout","t":"Open it in the browser. You should see the heading and the search box."}],"id":"create-the-project"},{"title":"Write loadPosts","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["In app.js:",false]]]},{"k":"code","t":"const statusEl = document.querySelector(\"#status\");\nconst postsEl = document.querySelector(\"#posts\");\nlet allPosts = [];\n\nasync function loadPosts() {\n  try {\n    const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\");\n    if (!res.ok) throw new Error(`Server answered ${res.status}`);\n    allPosts = await res.json();\n    console.log(allPosts.length); // should print 100\n  } catch (err) {","lang":"javascript"},{"k":"code","t":"    console.error(err);\n  }\n}\n\nloadPosts();","lang":"javascript"},{"k":"callout","t":"You should see 100 in the Console. fetch does not fail on a 404 or 500 by itself, which is why the res.ok check matters."}],"id":"write-loadposts"},{"title":"Show the first 10 posts as cards","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Add a render function, and call it after the data arrives:",false]]]},{"k":"code","t":"function render(posts) {\n  postsEl.innerHTML = \"\";\n  posts.slice(0, 10).forEach((p) => {\n    const card = document.createElement(\"article\");\n    card.innerHTML = `<h3>${p.title}</h3><p>${p.body}</p>`;\n    postsEl.appendChild(card);\n  });\n}","lang":"javascript"},{"k":"callout","t":"Call render(allPosts); right after allPosts = await res.json();. You should see ten cards on the page."}],"id":"show-the-first-10-posts-as-cards"},{"title":"Loading and error messages","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Update loadPosts so the user always knows what is happening:",false]]]},{"k":"code","t":"async function loadPosts() {\n  statusEl.textContent = \"Loading...\";\n  try {\n    const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\");\n    if (!res.ok) throw new Error(`Server answered ${res.status}`);\n    allPosts = await res.json();\n    statusEl.textContent = \"\";\n    render(allPosts);\n  } catch (err) {\n    statusEl.textContent = \"Sorry, the posts could not be loaded. Please try again.\";","lang":"javascript"},{"k":"code","t":"  }\n}","lang":"javascript"},{"k":"callout","t":"Reload the page. You should see \"Loading...\" for a moment, then the cards."}],"id":"loading-and-error-messages"},{"title":"Test the error path","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Misspell the URL (for example postz) and reload.",false]],[["You should see your friendly message, not a blank page.",false]],[["Fix the URL again.",false]]]}],"id":"test-the-error-path"},{"title":"Check your tools and create the project","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"code","t":"node -v\nnpm -v\nmkdir notices-cli\ncd notices-cli\nnpm init -y","lang":"bash"},{"k":"callout","t":"You should see two version numbers (Node 18 or newer), and a new package.json in the folder. If node is not found, reinstall Node from nodejs.org and reopen the terminal."}],"id":"check-your-tools-and-create-the-project"},{"title":"Write hello.js","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Create hello.js:",false]]]},{"k":"code","t":"console.log(\"Hello from Node!\");\nconsole.log(\"Arguments:\", process.argv.slice(2));","lang":"javascript"},{"k":"callout","t":"Run node hello.js one two. You should see Hello from Node! and Arguments: [ 'one', 'two' ]."}],"id":"write-hello-js"},{"title":"Create the data file and read it","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["Create notices.json:",false]]]},{"k":"code","t":"[\n  { \"id\": 1, \"title\": \"Library hours extended\", \"message\": \"Open until 9 PM during midterm week.\" }\n]","lang":"json"},{"k":"callout","t":"Then create cli.js and read the file with the fs module:"},{"k":"code","t":"const fs = require(\"fs\");\n\nfunction readNotices() {\n  return JSON.parse(fs.readFileSync(\"notices.json\", \"utf8\"));\n}\n\nconsole.log(readNotices());","lang":"javascript"},{"k":"callout","t":"Run node cli.js. You should see the array with one notice."}],"id":"create-the-data-file-and-read-it"},{"title":"Add the list and add commands","tag":"STEP 10","kind":"step","step":10,"blocks":[{"k":"list","items":[[["Replace the contents of cli.js:",false]]]},{"k":"code","t":"const fs = require(\"fs\");\n\nfunction readNotices() {\n  return JSON.parse(fs.readFileSync(\"notices.json\", \"utf8\"));\n}\n\nfunction writeNotices(notices) {\n  fs.writeFileSync(\"notices.json\", JSON.stringify(notices, null, 2));\n}\n\nconst [command, title, message] = process.argv.slice(2);","lang":"javascript"},{"k":"code","t":"\nif (command === \"list\") {\n  readNotices().forEach((n) => console.log(`${n.id}. ${n.title}: ${n.message}`));\n} else if (command === \"add\") {\n  if (!title || !message) {\n    console.log('Usage: node cli.js add \"Title\" \"Message\"');\n  } else {\n    const notices = readNotices();\n    const nextId = notices.length ? notices[notices.length - 1].id + 1 : 1;\n    notices.push({ id: nextId, title, message });\n    writeNotices(notices);\n    console.log(`Added notice ${nextId}.`);","lang":"javascript"},{"k":"code","t":"  }\n} else {\n  console.log('Commands: list | add \"Title\" \"Message\"');\n}","lang":"javascript"},{"k":"callout","t":"Try it:"},{"k":"code","t":"node cli.js list\nnode cli.js add \"Enrollment reminder\" \"Last day to add or drop is Friday.\"\nnode cli.js list","lang":"bash"},{"k":"callout","t":"You should see Added notice 2. and then both notices listed. Open notices.json and confirm the new notice is saved in the file."}],"id":"add-the-list-and-add-commands"},{"title":"Install nodemon and add scripts","tag":"STEP 11","kind":"step","step":11,"blocks":[{"k":"code","t":"npm install --save-dev nodemon","lang":"bash"},{"k":"callout","t":"Open package.json and set the scripts section:"},{"k":"code","t":"\"scripts\": {\n  \"start\": \"node server.js\",\n  \"dev\": \"nodemon server.js\"\n}","lang":"javascript"},{"k":"callout","t":"You should see a devDependencies section containing nodemon, and a new node_modules folder."}],"id":"install-nodemon-and-add-scripts"},{"title":"Run the plain http server from the lecture","tag":"STEP 12","kind":"step","step":12,"blocks":[{"k":"list","items":[[["Create server.js with the no-library server from the lecture above.",false]],[["Start it with npm run dev, then open http://localhost:3001 in the browser and in Postman.",false]],[["You should see the same answer in both.",false]]]}],"extra":["Change the response text, save, and watch nodemon restart the server by itself. Stop it with Ctrl+C."],"id":"run-the-plain-http-server-from-the-lecture"},{"title":"Add .gitignore","tag":"STEP 13","kind":"step","step":13,"blocks":[{"k":"list","items":[[["Create a file named .gitignore containing one line, node_modules/.",false]],[["Then show your instructor your package.json, the working list and add commands, and the running server.",false]]]}],"id":"add-gitignore"},{"kind":"step","title":"Push your project to GitHub","tag":"STEP 14","step":14,"blocks":[{"k":"list","items":[[["Create a free account at github.com if you do not have one. Click New repository, name it notices-cli, leave it empty (no README), and click Create.",false]],[["Copy the commands GitHub shows under \"push an existing repository\" and run them in your project folder:",false]]]},{"k":"code","t":"git init\ngit add .\ngit commit -m \"Add notices CLI and npm setup\"\ngit branch -M main\ngit remote add origin https://github.com/<your-username>/notices-cli.git\ngit push -u origin main","lang":"bash"},{"k":"list","items":[[["Refresh the repository page. You should see your files, but not node_modules.",false]],[["Repeat for the fetch page: create a second repository named notices-fetch and push that project too.",false]],[["Copy both repository links for Google Classroom.",false]]]}],"extra":["If Git asks you to sign in, follow the browser prompt. If it says `remote origin already exists`, run `git remote set-url origin <the new link>`."],"id":"push-your-project-to-github"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The page loads 10 posts as cards and shows \"Loading...\" while waiting.",false]],[["A wrong URL shows your friendly error message.",false]],[["node cli.js list and node cli.js add \"T\" \"M\" both work, and notices.json is updated.",false]],[["package.json has start and dev scripts and nodemon in devDependencies, and .gitignore lists node_modules/.",false]],[["The http server answers in the browser and in Postman.",false]],[["Both projects are on GitHub, without node_modules, and you have the two links.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a search box that filters the posts by title, and send a POST request to https://jsonplaceholder.typicode.com/posts with fetch. Log the 201 response and explain what the Network tab shows. Or pick another public JSON API, such as public holidays or weather, show three useful fields and add a Reload button."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: Asynchronous JavaScript","path":"downloads/laboratory/Week_03_Laboratory_Asynchronous_JavaScript.pptx"},{"label":"Earlier deck: Node.js and npm","path":"downloads/laboratory/Week_04_Laboratory_Node_js_and_npm.pptx"}],"pptx":"downloads/laboratory/Week_03_Laboratory_Asynchronous_JavaScript.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 5","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Explain callbacks, Promises and async/await and use them correctly.","Fetch JSON from a public API with loading and error handling.","Explain how Node.js runs JavaScript outside the browser.","Initialize projects with npm and publish them to GitHub."],"topics":{"lecture":["Callbacks, Promises and async/await","Fetch API, JSON and error handling with try/catch","Node.js runtime versus the browser; CommonJS and ES modules","npm, package.json, scripts and dependencies","Git and GitHub workflow"],"laboratory":["Fetch and display data from a public API with loading and error states","Write and run scripts in Node.js","Initialize a project with npm, install packages and push it to GitHub"]},"methods":["Lecture with live coding","Problem-based learning (public API task)","Lecture-demo (terminal)","Peer code review (GitHub)"],"resources":["Node.js 18+; npm; Git; GitHub; VS Code; a public REST API","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 5 materials","Flanagan (2020), chapters on asynchronous JavaScript and Node","OpenJS Foundation (n.d.), Node.js documentation","Mozilla Developer Network (n.d.), JavaScript guide"],"assessment":["Quiz 4: Promises and async/await","Lab 5 output: public-API fetch page and Node program pushed to GitHub","Google Classroom activity: debug an async function"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Asynchronous programming, command-line and version-control skills are expected of entry-level developers."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"Consuming open APIs trains students to build on existing digital infrastructure."}]}},{"week":6,"title":"First Express server; in-memory CRUD API","focus":"Routes, middleware and CRUD, tested in Postman","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build an Express server with routes and your own middleware, then turn it into a complete in-memory CRUD API for notices and prove that it works with a Postman collection. This is where the Campus Notices Board API begins.",false]],[["Deliverable. ",true],["Project Checkpoint 1: a project folder notices-api with a logger middleware, a static page, the five CRUD routes and the 404 handler, plus an exported Postman collection that contains at least ten requests with passing tests.",false]]]}],"extra":["Your collection must include these failure cases: an empty title, a missing body, an unknown id on GET, PUT and DELETE."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: first Express server and in-memory CRUD API","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-first-express-server-and-in-m"},{"title":"Create the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"mkdir notices-api\ncd notices-api\nnpm init -y\nnpm install express cors\nnpm install --save-dev nodemon","lang":"bash"},{"k":"callout","t":"Open package.json and set the scripts to \"start\": \"node server.js\" and \"dev\": \"nodemon server.js\". You should see express under dependencies and nodemon under devDependencies."}],"id":"create-the-project"},{"title":"Write the first two routes","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Create server.js:",false]]]},{"k":"code","t":"const express = require(\"express\");\nconst cors = require(\"cors\");\nconst app = express();\n\napp.use(cors());\napp.use(express.json());\nconst PORT = 3001;\n\napp.get(\"/\", (req, res) => {\n  res.send(\"Hello from Express\");\n});\n\napp.get(\"/api/health\", (req, res) => {\n  res.json({ status: \"ok\" });\n});","lang":"javascript"},{"k":"code","t":"\napp.listen(PORT, () => console.log(`Running at http://localhost:${PORT}`));","lang":"javascript"},{"k":"callout","t":"Run npm run dev. You should see Running at http://localhost:3001. Open that address in the browser to see \"Hello from Express\", then open http://localhost:3001/api/health to see {\"status\":\"ok\"}."}],"id":"write-the-first-two-routes"},{"title":"Write the logger middleware","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Add it above every route, right after const PORT = 3001;:",false]]]},{"k":"code","t":"function logger(req, res, next) {\n  console.log(`${req.method} ${req.url}`);\n  next();\n}\napp.use(logger);","lang":"javascript"},{"k":"list","items":[[["Refresh a few pages.",false]]]},{"k":"list","items":[[["The terminal should print one line per request, such as GET /api/notices/2.",false]],[["Now try an experiment: cut the app.use(logger) line and paste it below the routes.",false]]]}],"extra":["The requests that a route answers stop appearing in the log, because the route answered before the logger got its turn. Put it back at the top. That is why order matters in Express."],"id":"write-the-logger-middleware"},{"title":"Serve your Week 3 page","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Create a folder named public inside the project and copy your Week 3 index.html and styles.css into it.",false]],[["Add this line above the routes, below the logger:",false]]]},{"k":"code","t":"app.use(express.static(\"public\"));","lang":"javascript"},{"k":"list","items":[[["Open http://localhost:3001/index.html.",false]]]},{"k":"list","items":[[["You should see your styled Campus Notices page, and the Network tab shows both files loading with 200.",false]],[["(Your GET / route still answers the address /, because routes and middleware run from top to bottom and your route is not blocked by the static line.",false]]]}],"extra":["Try moving the GET / route below express.static and see which one answers / then.)"],"id":"serve-your-week-3-page"},{"kind":"step","title":"Add the in-memory store, the list route and the single-notice route","tag":"STEP 5","step":5,"blocks":[{"k":"list","items":[[["Add this above the `app.listen` line. It adds a notices array to act as your database, a small `validateNotice` helper that you will use in the POST and PUT routes, and the two read routes.",false]]]},{"k":"code","t":"let notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM.\", createdAt: \"2026-10-12T08:00:00.000Z\" },\n];\nlet nextId = 2;\n\n// returns an error message, or null when the notice is valid\nfunction validateNotice(body) {\n  const { title, message } = body || {};\n  if (typeof title !== \"string\" || title.trim() === \"\") return \"Title is required.\";\n  if (typeof message !== \"string\" || message.trim() === \"\") return \"Message is required.\";\n  if (title.trim().length > 100) return \"Title must be 100 characters or fewer.\";\n  return null;\n}\n\napp.get(\"/api/notices\", (req, res) => {\n  const { search } = req.query;\n  if (search) {\n    return res.json(notices.filter((n) => n.title.toLowerCase().includes(search.toLowerCase())));\n  }\n  res.json(notices);\n});\n\napp.get(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);\n});","lang":"javascript"},{"k":"p","t":"Check GET /api/notices (one notice), GET /api/notices/1 (that notice), GET /api/notices/99 (a 404) and GET /api/notices?search=lib (the matching notice). The `return` before the 404 answer stops the function, so the route never answers twice."}],"extra":["`validateNotice` is a plain helper for now. In Week 7 you turn it into middleware and learn how to return good error responses."],"id":"add-the-in-memory-store-the-list-route-and-the-s"},{"kind":"step","title":"Add the POST route","tag":"STEP 6","step":6,"blocks":[{"k":"code","t":"app.post(\"/api/notices\", (req, res) => {\n  const problem = validateNotice(req.body);\n  if (problem) return res.status(400).json({ error: problem });\n\n  const notice = {\n    id: nextId++,\n    title: req.body.title.trim(),\n    message: req.body.message.trim(),\n    createdAt: new Date().toISOString(),\n  };\n  notices.push(notice);\n  res.status(201).json(notice);\n});","lang":"javascript"},{"k":"p","t":"In Postman, a good POST gives 201 with the new notice, and a POST with { \"title\": \"\" } gives 400."}],"id":"add-the-post-route"},{"title":"Add PUT and DELETE","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Put these above app.listen:",false]]]},{"k":"code","t":"app.put(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  const problem = validateNotice(req.body);\n  if (problem) return res.status(400).json({ error: problem });\n  notice.title = req.body.title.trim();\n  notice.message = req.body.message.trim();\n  res.json(notice);\n});","lang":"javascript"},{"k":"code","t":"app.delete(\"/api/notices/:id\", (req, res) => {\n  const index = notices.findIndex((n) => n.id === Number(req.params.id));\n  if (index === -1) return res.status(404).json({ error: \"Notice not found.\" });\n  notices.splice(index, 1);\n  res.status(204).send();\n});","lang":"javascript"},{"k":"callout","t":"Test: PUT /api/notices/1 with a new title gives 200; DELETE /api/notices/1 gives 204 with an empty body; the same DELETE again gives 404."}],"id":"add-put-and-delete"},{"title":"Add the 404 and error handlers at the bottom","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["They must be the last things before app.listen:",false]]]},{"k":"code","t":"app.use((req, res) => {\n  res.status(404).json({ error: \"Route not found\" });\n});\n\n// error-handling middleware has FOUR parameters\napp.use((err, req, res, next) => {\n  console.error(err);\n  res.status(500).json({ error: \"Something went wrong\" });\n});","lang":"javascript"},{"k":"callout","t":"Open /nope. You should see { \"error\": \"Route not found\" }. To test the error handler, add this temporary route above the 404 handler, open /api/boom, confirm you get a 500 JSON answer, then delete the route:"},{"k":"code","t":"app.get(\"/api/boom\", () => {\n  throw new Error(\"test error\");\n});","lang":"javascript"}],"id":"add-the-404-and-error-handlers-at-the-bottom"},{"title":"Create the Postman collection","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["In Postman, click New, then Collection, and name it Notices API.",false]],[["Open the collection's Variables tab, add baseUrl with the value http://localhost:3001, and save.",false]],[["Add a request for every row in the table below. Use {{baseUrl}}/api/notices as the URL start. For requests with a body, choose Body, raw, JSON.",false]]]},{"k":"table","head":["#","Request","Expected status"],"rows":[["1","GET {{baseUrl}}/api/notices","200"],["2","GET {{baseUrl}}/api/notices/1","200"],["3","GET {{baseUrl}}/api/notices/999","404"],["4","POST with a valid title and message","201"],["5","POST with an empty title","400"],["6","POST with no body","400"],["7","PUT /api/notices/1 with valid data","200"],["8","PUT /api/notices/999 with valid data","404"],["9","PUT /api/notices/1 with an empty title","400"],["10","DELETE /api/notices/999","404"],["11","DELETE an existing notice","204"],["12","GET /api/notices?search=lib","200"]]},{"k":"list","items":[[["Send each one and check the status.",false]],[["Restart the server (Ctrl+C, then npm run dev) whenever your data changes so the requests start from a known state.",false]]]}],"id":"create-the-postman-collection"},{"title":"Add tests to at least five requests","tag":"STEP 10","kind":"step","step":10,"blocks":[{"k":"list","items":[[["Open a request, choose the Scripts tab (called Tests in older versions), and paste a check.",false]],[["Examples:",false]]]},{"k":"code","t":"pm.test(\"Status is 201\", () => pm.response.to.have.status(201));\n\npm.test(\"Response has a numeric id\", () => {\n  pm.expect(pm.response.json().id).to.be.a(\"number\");\n});\n\npm.test(\"Error message is a string\", () => {","lang":"javascript"},{"k":"code","t":"  pm.expect(pm.response.json().error).to.be.a(\"string\");\n});","lang":"javascript"},{"k":"callout","t":"Send the request again. In the Test Results panel you should see a green PASS for each check. Add checks for status codes on the failure cases too."}],"id":"add-tests-to-at-least-five-requests"},{"title":"Export and show your instructor","tag":"STEP 11","kind":"step","step":11,"blocks":[{"k":"list","items":[[["Right-click the collection, choose Export, pick the Collection v2.1 format, and save the JSON file in your project folder.",false]],[["Your collection must include these failure cases: an empty title, a missing body, and an unknown id on GET, PUT and DELETE.",false]]]}],"id":"export-and-show-your-instructor"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["All five notices routes work and return the right status codes (200, 201, 204, 400, 404).",false]],[["The logger prints one line for every request, and you can say why it must come before the routes.",false]],[["The static page from Week 3 is served, and unknown routes return a JSON 404 from a handler registered last.",false]],[["The collection has at least ten requests and at least five have passing pm.test checks.",false]],[["The exported JSON file is in your project folder.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add PATCH /api/notices/:id that updates only the fields the client sends. Decide how validation should behave when only one field is present, and write two Postman tests that prove it."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: Express routing and middleware","path":"downloads/laboratory/Week_05_Laboratory_Express_routing_and_middleware.pptx"},{"label":"Earlier deck: REST design and Postman","path":"downloads/laboratory/Week_06_Laboratory_REST_design_status_codes_and_validation.pptx"}],"pptx":"downloads/laboratory/Week_05_Laboratory_Express_routing_and_middleware.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 6","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Build a web server with Express routes and middleware.","Design RESTful routes using correct methods, resource names and status codes.","Implement CRUD routes for notices in memory.","Test an API using Postman or Thunder Client."],"topics":{"lecture":["Express application, routes, route parameters and query strings","Built-in and custom middleware","REST principles and resource naming","HTTP methods and status codes in API responses"],"laboratory":["Build an Express server with routes and middleware","Implement CRUD routes for notices (in memory)","Test the API with Postman or Thunder Client; the Campus Notices Board API begins"]},"methods":["Lecture with live coding","API design workshop","Project-based lab (Campus Notices Board)","Peer feedback"],"resources":["Node.js; Express; Postman or Thunder Client; VS Code","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 6 materials","OpenJS Foundation (n.d.), Express documentation","Fielding et al. (2022), RFC 9110 (status codes)","Mozilla Developer Network (n.d.), HTTP response status codes"],"assessment":["Quiz 5: Express, middleware and REST","Lab 6 output: in-memory CRUD API with a Postman collection","Project Checkpoint 1: Notices API"],"sdg":[{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"RESTful APIs are the building blocks of modern digital services and local innovation."},{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Back-end API design is a core, employable full-stack skill."},{"goal":"SDG 16: Peace, Justice and Strong Institutions","target":"Target 16.10: Ensure public access to information and protect fundamental freedoms, in accordance with national legislation and international agreements.","link":"Well-designed APIs make public information (such as campus notices) accessible to many clients."}]}},{"week":7,"title":"Validation; connect the API to a database","focus":"Add input validation and error responses, connect Express to MongoDB, create the Notice model","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Add input validation and a consistent error response to the notices API. Then move your Week 6 notices out of the array and into MongoDB, starting with reading data.",false]],[["Deliverable. ",true],["A running API that rejects bad input with a clear 400 message, whose GET /api/notices returns notices stored in MongoDB, with a seed.js script and a screenshot of your documents in Atlas or MongoDB Compass.",false]]]}],"extra":["If your first connection fails, read the first line of the error. It usually says whether the problem is the password, the allowed IP address, or a typo in the string."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: validation and the MongoDB connection","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-validation-and-the-mongodb-co"},{"kind":"step","title":"Copy your Week 6 project","tag":"STEP 1","step":1,"blocks":[{"k":"list","items":[[["Copy your Week 6 folder to a new folder named notices-api-mongo and open it in VS Code. Run `npm install` inside it, then `npm run dev`, and check that GET /api/notices still works.",false]]]}],"id":"copy-your-week-6-project"},{"kind":"step","title":"Move validation into its own middleware","tag":"STEP 2","step":2,"blocks":[{"k":"list","items":[[["Create validate.js. It turns the checking function from Week 6 into middleware that you can attach to any route.",false]]]},{"k":"code","t":"function validateNotice(req, res, next) {\n  const { title, message } = req.body || {};\n  const errors = [];\n\n  if (typeof title !== \"string\" || title.trim() === \"\") {\n    errors.push(\"Title is required.\");\n  } else if (title.trim().length > 100) {\n    errors.push(\"Title must be 100 characters or fewer.\");\n  }\n  if (typeof message !== \"string\" || message.trim() === \"\") {\n    errors.push(\"Message is required.\");\n  }\n\n  if (errors.length > 0) {\n    return res.status(400).json({ error: errors[0], errors });\n  }\n  next();\n}\n\nmodule.exports = validateNotice;","lang":"javascript"},{"k":"list","items":[[["In server.js, add `const validateNotice = require(\"./validate\");` and put it in front of the handlers of the POST and PUT routes, for example `app.post(\"/api/notices\", validateNotice, (req, res) => { ... })`. Delete the old `validateNotice` function and the `problem` checks inside those two handlers.",false]]]}],"extra":["The middleware answers with 400 and never calls `next()` when the input is bad, so the route handler runs only for valid data."],"id":"move-validation-into-its-own-middleware"},{"kind":"step","title":"Return one error shape everywhere","tag":"STEP 3","step":3,"blocks":[{"k":"list","items":[[["Every error your API sends should look the same: `{ \"error\": \"message\" }`. Check your 404 responses and the error handler at the bottom of server.js.",false]],[["Make sure an invalid JSON body, such as `{ \"title\": `, also returns your JSON error. Express raises a `SyntaxError` for it. Add this branch to the error handler at the bottom:",false]]]},{"k":"code","t":"app.use((err, req, res, next) => {\n  if (err.type === \"entity.parse.failed\") {\n    return res.status(400).json({ error: \"Invalid JSON body.\" });\n  }\n  console.error(err);\n  res.status(500).json({ error: \"Something went wrong.\" });\n});","lang":"javascript"}],"id":"return-one-error-shape-everywhere"},{"kind":"step","title":"Test the bad input on purpose","tag":"STEP 4","step":4,"blocks":[{"k":"table","head":["Request","Expected"],"rows":[["POST with a valid title and message","201"],["POST with no body","400, \"Title is required.\""],["POST with { \"title\": \"   \", \"message\": \"x\" }","400, \"Title is required.\""],["POST with a title of 101 characters","400, \"Title must be 100 characters or fewer.\""],["POST with { \"title\": 42, \"message\": \"x\" }","400"],["POST with a broken JSON body","400, \"Invalid JSON body.\""],["PUT /api/notices/1 with an empty message","400"]]},{"k":"p","t":"Run your whole Week 6 Postman collection too. It should still pass."}],"id":"test-the-bad-input-on-purpose"},{"title":"Get a database","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Choose one:",false]],[["MongoDB Atlas (free). Create an account, create a free cluster, add a database user (note the username and password), and under Network Access allow your IP address. Click Connect, choose Drivers, and copy the connection string. Replace <password> with your real password, and add the database name before the ?, for example ...mongodb.net/campus-notices?retryWrites=true.",false]],[["Local MongoDB. Install it, start the server, and use mongodb://127.0.0.1:27017/campus-notices.",false]]]},{"k":"list","items":[[["You should have one connection string saved in a text file for now.",false]],[["If the school network blocks Atlas, use the local install.",false]]]}],"id":"get-a-database"},{"title":"Prepare the project","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["In the same folder, run:",false]]]},{"k":"code","t":"npm install mongoose dotenv","lang":"bash"},{"k":"callout","t":"Create a .env file with your string, and add .env to .gitignore:"},{"k":"code","t":"# .env\nMONGODB_URI=mongodb://127.0.0.1:27017/campus-notices","lang":"javascript"},{"k":"code","t":"# .gitignore\nnode_modules/\n.env","lang":"text"}],"id":"prepare-the-project"},{"title":"Write db.js and connect","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Create db.js:",false]]]},{"k":"code","t":"require(\"dotenv\").config();\nconst mongoose = require(\"mongoose\");\n\nasync function connectDB() {\n  try {\n    await mongoose.connect(process.env.MONGODB_URI);\n    console.log(\"MongoDB connected\");\n  } catch (err) {\n    console.error(\"MongoDB connection failed:\", err.message);\n    process.exit(1);\n  }","lang":"javascript"},{"k":"code","t":"}\n\nmodule.exports = connectDB;","lang":"javascript"},{"k":"callout","t":"At the top of server.js, add const connectDB = require(\"./db\");. At the bottom, replace the app.listen(...) line with:"},{"k":"code","t":"connectDB().then(() => {\n  app.listen(3001, () => console.log(\"API on http://localhost:3001\"));\n});","lang":"javascript"},{"k":"callout","t":"Run npm run dev. You should see MongoDB connected and then API on http://localhost:3001. If you see an error, read its first line:"},{"k":"table","head":["First line says","Likely cause"],"rows":[["bad auth or Authentication failed","Wrong username or password in the string"],["ENOTFOUND or timed out","Typo in the host name, or your IP address is not allowed in Atlas"],["ECONNREFUSED 127.0.0.1","The local MongoDB server is not running"],["MONGODB_URI is undefined","The .env file is missing, misnamed, or in the wrong folder"]]}],"id":"write-db-js-and-connect"},{"title":"Write the model","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Create models/Notice.js:",false]]]},{"k":"code","t":"const mongoose = require(\"mongoose\");\n\nconst noticeSchema = new mongoose.Schema(\n  {\n    title: { type: String, required: true, trim: true, maxlength: 100 },\n    message: { type: String, required: true, trim: true, maxlength: 500 },\n  },\n  { timestamps: true } // adds createdAt and updatedAt automatically\n);\n\nmodule.exports = mongoose.model(\"Notice\", noticeSchema);","lang":"javascript"}],"id":"write-the-model"},{"title":"Write and run seed.js","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["This script puts starter data in the database so you do not type it by hand:",false]]]},{"k":"code","t":"const mongoose = require(\"mongoose\");\nconst connectDB = require(\"./db\");\nconst Notice = require(\"./models/Notice\");\n\nasync function seed() {\n  await connectDB();\n  await Notice.deleteMany({});\n  await Notice.insertMany([","lang":"javascript"},{"k":"code","t":"    { title: \"Library hours extended\", message: \"Open until 9 PM during midterm week.\" },\n    { title: \"Enrollment reminder\", message: \"Last day to add or drop subjects is Friday.\" },\n    { title: \"Programming contest\", message: \"Sign up at the CCS office by Monday.\" },\n  ]);\n  console.log(\"Seeded 3 notices\");\n  await mongoose.disconnect();\n}\n\nseed();","lang":"javascript"},{"k":"callout","t":"Run node seed.js. You should see Seeded 3 notices. Open Atlas (Browse Collections) or MongoDB Compass and find the notices collection with three documents. Take your screenshot now."}],"id":"write-and-run-seed-js"},{"title":"Read from the database","tag":"STEP 10","kind":"step","step":10,"blocks":[{"k":"list","items":[[["In server.js, add const Notice = require(\"./models/Notice\"); and replace the two GET routes:",false]]]},{"k":"code","t":"app.get(\"/api/notices\", async (req, res) => {\n  const notices = await Notice.find().sort({ createdAt: -1 });\n  res.json(notices);\n});\n\napp.get(\"/api/notices/:id\", async (req, res) => {\n  try {\n    const notice = await Notice.findById(req.params.id);","lang":"javascript"},{"k":"code","t":"    if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n    res.json(notice);\n  } catch (err) {\n    if (err.name === \"CastError\") return res.status(400).json({ error: \"Invalid id.\" });\n    res.status(500).json({ error: \"Something went wrong.\" });\n  }\n});","lang":"javascript"},{"k":"callout","t":"In Postman, GET /api/notices should return three notices. Look at one: its identifier is _id, a long string, not id. Copy one _id and GET /api/notices/<that id> to see a single notice. Try GET /api/notices/abc and confirm a 400."}],"id":"read-from-the-database"},{"title":"Prove the data is persistent","tag":"STEP 11","kind":"step","step":11,"blocks":[{"k":"list","items":[[["Stop the server (Ctrl+C), start it again, and GET /api/notices.",false]],[["The three notices are still there.",false]],[["Compare that with Week 6, where a restart emptied the array.",false]]]}],"id":"prove-the-data-is-persistent"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["Bad input gets a 400 with a clear message from the validation middleware, and every error has the same JSON shape.",false]],[["You see MongoDB connected each time the server starts.",false]],[["GET /api/notices and GET /api/notices/:id read from MongoDB.",false]],[["seed.js works, .env is in .gitignore, and you have the screenshot of your documents.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a category field to the schema that accepts only \"general\", \"academic\" or \"event\" and defaults to \"general\". Let GET /api/notices?category=event filter the results."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: REST design and Postman","path":"downloads/laboratory/Week_06_Laboratory_REST_design_status_codes_and_validation.pptx"},{"label":"Earlier deck: MongoDB and Mongoose basics","path":"downloads/laboratory/Week_07_Laboratory_MongoDB_and_Mongoose_basics.pptx"}],"pptx":"downloads/laboratory/Week_06_Laboratory_REST_design_status_codes_and_validation.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 7","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Validate input and return meaningful error responses.","Explain document databases and model data with Mongoose schemas.","Connect an Express API to MongoDB.","Create and read documents with Mongoose."],"topics":{"lecture":["Input validation and error responses","Document databases and MongoDB basics","Mongoose schemas, models and validation","Connecting Express to MongoDB; creating and reading documents"],"laboratory":["Add input validation and error responses to the notices API","Connect Express to MongoDB (Atlas or local)","Create the Notice model and implement create and read with Mongoose"]},"methods":["Lecture with live coding","Database lab","Debugging clinic","Project-based learning (Campus Notices Board)"],"resources":["MongoDB Atlas or MongoDB Community Server; Mongoose; Postman","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 7 materials","Mongoose (n.d.), Mongoose documentation","OpenJS Foundation (n.d.), Express documentation"],"assessment":["Short quiz: validation and error responses","Lab 7 output: API connected to MongoDB with the Notice model"],"sdg":[{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"Data persistence is the foundation of information systems used by industry and government."},{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Database skills are in demand across ICT employment."}]}},{"week":8,"title":"Persistent API; review and debugging clinic","focus":"Replace in-memory data with Mongoose models and review the MERN back end","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Rebuild your Week 6 API on top of MongoDB with a clean, layered structure.",false]],[["Deliverable. ",true],["A server with routes, controllers, a model and an error handler. Every route works, data survives a restart, and your Postman collection from Week 6 passes with only small changes.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: persistent API","tag":null,"kind":"divider","sub":"You are rebuilding the same API in a cleaner structure.","id":"step-by-step-guide-persistent-api"},{"title":"Create the folder structure","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["In your Week 7 project, run:",false]]]},{"k":"code","t":"mkdir controllers routes middleware","lang":"bash"},{"k":"callout","t":"You should end up with this layout (move Notice.js and db.js if they are not already there):"},{"k":"code","t":"server/\n  app.js\n  server.js\n  db.js\n  models/Notice.js\n  controllers/noticeController.js\n  routes/notices.js\n  middleware/asyncHandler.js\n  middleware/errorHandler.js","lang":"javascript"}],"id":"create-the-folder-structure"},{"title":"Write app.js and server.js","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["app.js builds the Express app and does not start listening. server.js connects to the database, then listens.",false]]]},{"k":"code","t":"// app.js\nconst express = require(\"express\");\nconst cors = require(\"cors\");\nconst noticeRoutes = require(\"./routes/notices\");\nconst errorHandler = require(\"./middleware/errorHandler\");\n\nconst app = express();\napp.use(cors());\napp.use(express.json());","lang":"javascript"},{"k":"code","t":"app.use(\"/api/notices\", noticeRoutes);\napp.use((req, res) => res.status(404).json({ error: \"Route not found.\" }));\napp.use(errorHandler); // registered LAST\n\nmodule.exports = app;","lang":"javascript"},{"k":"code","t":"// server.js\nrequire(\"dotenv\").config();\nconst app = require(\"./app\");\nconst connectDB = require(\"./db\");\n\nconst PORT = process.env.PORT || 3001;","lang":"javascript"},{"k":"code","t":"\nconnectDB().then(() => {\n  app.listen(PORT, () => console.log(`API on http://localhost:${PORT}`));\n});","lang":"javascript"}],"id":"write-app-js-and-server-js"},{"title":"Write the controller and the router","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"// controllers/noticeController.js\nconst Notice = require(\"../models/Notice\");\nconst asyncHandler = require(\"../middleware/asyncHandler\");\n\nexports.getNotices = asyncHandler(async (req, res) => {\n  const notices = await Notice.find().sort({ createdAt: -1 });\n  res.json(notices);\n});\n\nexports.getNotice = asyncHandler(async (req, res) => {\n  const notice = await Notice.findById(req.params.id);\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);","lang":"javascript"},{"k":"code","t":"});\n\nexports.createNotice = asyncHandler(async (req, res) => {\n  const { title, message } = req.body;\n  const notice = await Notice.create({ title, message });\n  res.status(201).json(notice);\n});\n\nexports.updateNotice = asyncHandler(async (req, res) => {\n  const { title, message } = req.body;\n  const notice = await Notice.findByIdAndUpdate(\n    req.params.id,\n    { title, message },\n    { new: true, runValidators: true }","lang":"javascript"},{"k":"code","t":"  );\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);\n});\n\nexports.deleteNotice = asyncHandler(async (req, res) => {\n  const notice = await Notice.findByIdAndDelete(req.params.id);\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.status(204).send();\n});","lang":"javascript"},{"k":"code","t":"// routes/notices.js\nconst express = require(\"express\");\nconst c = require(\"../controllers/noticeController\");\n\nconst router = express.Router();\nrouter.get(\"/\", c.getNotices);\nrouter.get(\"/:id\", c.getNotice);\nrouter.post(\"/\", c.createNotice);\nrouter.put(\"/:id\", c.updateNotice);\nrouter.delete(\"/:id\", c.deleteNotice);\n\nmodule.exports = router;","lang":"javascript"}],"id":"write-the-controller-and-the-router"},{"title":"Write the two middleware files","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"// middleware/asyncHandler.js\nmodule.exports = (fn) => (req, res, next) =>\n  Promise.resolve(fn(req, res, next)).catch(next);","lang":"javascript"},{"k":"code","t":"// middleware/errorHandler.js\nmodule.exports = (err, req, res, next) => {\n  if (err.name === \"ValidationError\") {\n    const message = Object.values(err.errors).map((e) => e.message).join(\" \");\n    return res.status(400).json({ error: message });\n  }\n  if (err.name === \"CastError\") {\n    return res.status(400).json({ error: \"Invalid id.\" });","lang":"javascript"},{"k":"code","t":"  }\n  console.error(err); // the real error stays on the server\n  res.status(500).json({ error: \"Something went wrong.\" });\n};","lang":"javascript"},{"k":"callout","t":"Run npm run dev. You should see MongoDB connected and API on http://localhost:3001. GET /api/notices should return your seeded notices."}],"id":"write-the-two-middleware-files"},{"title":"Run your Week 6 collection","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Open your Postman collection and run every request.",false]],[["Some will fail.",false]]]}],"extra":["The usual reasons: ids in the URLs are numbers (1) but MongoDB ids are long strings, so replace them with a real _id copied from GET /api/notices; and a test that checks for a numeric id should now check for _id. Fix the requests until all pass."],"id":"run-your-week-6-collection"},{"title":"Test the bad cases on purpose","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"table","head":["Request","Expected result"],"rows":[["POST with an empty title","400 and a message from the schema"],["GET /api/notices/abc","400 and Invalid id."],["GET /api/notices/507f1f77bcf86cd799439011 (valid-looking, but no such notice)","404 and Notice not found."],["DELETE the same id twice","204, then 404"]]},{"k":"list","items":[[["If the invalid-id request hangs or crashes, check that you wrapped every controller in asyncHandler and that errorHandler is registered last.",false]]]}],"id":"test-the-bad-cases-on-purpose"},{"title":"Prove it persists","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Stop and restart the server, then GET /api/notices.",false]],[["The data should be there.",false]]]}],"id":"prove-it-persists"},{"title":"Complete the review checklist","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Go back to the Weeks 1 to 8 review table in the lecture.",false]],[["Mark each row honestly as \"I can do this\" or \"I need to revisit this\".",false]],[["Bring your list to the midterm preparation.",false]]]}],"id":"complete-the-review-checklist"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The server follows the folder layout above, and errorHandler is registered last.",false]],[["Every route works, and the bad-case table gives the expected codes.",false]],[["Your Week 6 collection passes with only small changes.",false]],[["Data survives a restart, and your checklist is complete.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add pagination: GET /api/notices?page=2&limit=5 returns the second page of five notices, and the response includes the total count so a client can build page links."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"decks":[{"label":"Earlier deck: Mongoose CRUD, error handling and review","path":"downloads/laboratory/Week_08_Laboratory_Mongoose_CRUD_error_handling_and_review.pptx"}],"pptx":"downloads/laboratory/Week_08_Laboratory_Mongoose_CRUD_error_handling_and_review.pptx","pptxNote":"The slides for this week come from the earlier outline, so they follow the old week order. This page follows the revised syllabus.","syllabus":{"label":"Week 8","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Implement create, read, update and delete operations with Mongoose.","Handle database and asynchronous errors with error-handling middleware.","Complete a persistent notices API.","Review and debug the MERN back end before the midterm."],"topics":{"lecture":["CRUD operations with Mongoose","Asynchronous error handling and error middleware","MERN back-end review"],"laboratory":["Replace in-memory data with Mongoose models","Complete a persistent notices API","Review and debugging clinic"]},"methods":["Lecture with live coding","Database lab","Debugging clinic","Review games"],"resources":["MongoDB Atlas or MongoDB Community Server; Mongoose; Postman","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 8 materials","Mongoose (n.d.), Mongoose documentation","OpenJS Foundation (n.d.), Express documentation"],"assessment":["Quiz 6: MongoDB and Mongoose","Lab 8 output: persistent CRUD API","Project Checkpoint 2: persistent notices API"],"sdg":[{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"Data persistence is the foundation of information systems used by industry and government."},{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Database skills are in demand across ICT employment."}]}},{"week":9,"title":"Midterm","focus":"midterm practical","duration":"3 hours","sections":[{"title":"The midterm practical","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["An individual practical exam on Weeks 1 to 8: web basics, JavaScript, Node.js, Express, REST and MongoDB with Mongoose.",false]],[["Your instructor gives you the task at the start of the session. You have 3 hours.",false]],[["The task is new, but every skill it needs comes from the Week 1 to 8 labs.",false]]]}],"id":"the-midterm-practical"},{"title":"Rules for the exam","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["You may use your own old code and the module.",false]],[["You may not use the internet or messaging apps.",false]],[["Work alone. Ask your instructor only about the computer, not the solution.",false]]]}],"id":"rules-for-the-exam"},{"title":"How to prepare","tag":"PREPARE","kind":"prepare","blocks":[{"k":"list","items":[[["Make sure your Week 4, 5, 6, 7 and 8 lab deliverables run.",false]],[["Practise building an Express and Mongoose API from an empty folder without copying and pasting.",false]],[["Practise testing every route in Postman, with a success case and a failure case.",false]]]}],"id":"how-to-prepare"},{"title":"On the day: plan first","tag":"EXAM DAY","kind":"examday","blocks":[{"k":"list","items":[[["Read the requirements twice, then plan on paper: the routes, the fields, and the status code for each case.",false]],[["Set up the project: npm init -y; install express, cors, mongoose, dotenv and nodemon.",false]],[["Add .gitignore with node_modules/ and .env before your first commit.",false]]]}],"id":"on-the-day-plan-first"},{"title":"On the day: build and test","tag":"EXAM DAY","kind":"examday","blocks":[{"k":"list","items":[[["Build one route at a time and test it in Postman before you write the next one.",false]],[["Build a Postman collection with success and failure cases, and save it with your project.",false]],[["Review before you submit: right methods, paths and status codes; validation errors return the error JSON; unknown and invalid ids are handled.",false]]]}],"id":"on-the-day-build-and-test"},{"title":"Time budget (suggested)","tag":"EXAM DAY","kind":"examday","blocks":[{"k":"table","head":["Stage","Minutes"],"rows":[["Read and plan","10"],["Set up the project","20"],["Model and structure","25"],["Build routes, one at a time","45"],["Query filter","20"],["Postman collection","30"],["Final review","15"]]},{"k":"callout","t":"If you run out of time, a working version with fewer routes earns more than an unfinished version of all of them."}],"id":"time-budget-suggested"},{"title":"Catch-up option","tag":"CATCH-UP","kind":"catchup","blocks":[{"k":"list","items":[[["A midterm week is also a good time to catch up if you have fallen behind.",false]],[["If your instructor has marked you for catch-up, finish these deliverables in order and show each one as you finish it.",false]]]},{"k":"table","head":["Order","Deliverable","From"],"rows":[["1","A page that fetches and displays data from a public API","Week 5"],["2","An Express server with at least four routes and a logger","Week 6"],["3","An in-memory CRUD API with validation and a Postman collection","Weeks 6 and 7"],["4","The same API connected to MongoDB","Weeks 7 and 8"]]}],"id":"catch-up-option"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_09_Laboratory_Midterm.pptx","slideCount":8,"pptx":"downloads/laboratory/Week_09_Laboratory_Midterm.pptx","syllabus":{"label":"Week 9","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Demonstrate mastery of Weeks 1-8: HTML and CSS, web fundamentals, JavaScript, Node.js, Express, REST and MongoDB/Mongoose.","Apply HTTP and REST reasoning to explain and debug API behaviour.","Implement a correct persistent API within a time limit."],"topics":{"lecture":["Midterm Examination","Written component: HTML and CSS, HTTP, JavaScript, Node.js, Express, REST design and MongoDB/Mongoose (Weeks 1-8)"],"laboratory":["Midterm Examination","Practical component: build and test a persistent CRUD API with Express and Mongoose"]},"methods":["Written examination","Practical / coding examination (Node.js, Express, Mongoose)","Individual performance assessment"],"resources":["VS Code; Node.js; MongoDB; Postman","Limson, H. D. (2026), CSAE 104 Web programming course site: Weeks 1-8 materials","Mozilla Developer Network (n.d.); OpenJS Foundation (n.d.); Mongoose (n.d.)"],"assessment":["Midterm Written Exam (40% of midterm grade)","Midterm Practical Exam (part of 60% class standing)","Midterm Grade = Class Standing (60%) + Midterm Exam (40%)"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.3: Ensure equal access for all women and men to affordable and quality technical, vocational and tertiary education.","link":"Summative assessment verifies the technical skills required for industry readiness."}]}},{"week":10,"title":"Install PostgreSQL; notices database","focus":"build the notices and categories tables","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Install PostgreSQL, build the notices and categories tables for the Campus Notices Board, and write CRUD and join queries against sample data.",false]],[["Deliverable. ",true],["Lab 10 output: a notices_db database and a file queries.sql with your CRUD and join queries, plus a screenshot of \\d notices and one join result.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: the notices database","tag":null,"kind":"divider","sub":"Run each statement in psql or in pgAdmin's Query Tool, and check the result before moving on.","id":"step-by-step-guide-the-notices-database"},{"title":"Install PostgreSQL and open psql","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Install PostgreSQL 14 or newer from postgresql.org. Keep psql and pgAdmin ticked, and write down the password for the postgres user.",false]]]},{"k":"code","t":"psql --version\npsql -U postgres","lang":"bash"},{"k":"callout","t":"A prompt ending in =# means you are connected. If psql is not found, add the PostgreSQL bin folder to your PATH or open SQL Shell (psql) from the Start menu. You may also use pgAdmin for every step."}],"id":"install-postgresql-and-open-psql"},{"title":"Create the database","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"CREATE DATABASE notices_db;\n\\c notices_db","lang":"sql"},{"k":"callout","t":"The prompt should now read notices_db=#. Run \\dt; it should say no relations found."}],"id":"create-the-database"},{"title":"Create the categories table","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"CREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name VARCHAR(30) NOT NULL UNIQUE\n);","lang":"sql"},{"k":"list","items":[[["Try to break it later: inserting the same name twice should fail.",false]]]}],"id":"create-the-categories-table"},{"title":"Create the notices table","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"CREATE TABLE notices (\n  id SERIAL PRIMARY KEY,\n  title VARCHAR(120) NOT NULL,\n  message TEXT NOT NULL,\n  category_id INTEGER REFERENCES categories(id),\n  pinned BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CHECK (length(trim(title)) > 0)\n);","lang":"sql"},{"k":"list","items":[[["Run \\d notices and take your first screenshot. You should see the foreign key and the CHECK rule listed.",false]]]}],"id":"create-the-notices-table"},{"title":"Insert sample data","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"code","t":"INSERT INTO categories (name) VALUES ('academic'), ('events'), ('urgent');\n\nINSERT INTO notices (title, message, category_id, pinned) VALUES\n  ('Library hours extended', 'Open until 9 PM.', 1, false),\n  ('Foundation Day program', 'Gym, 8 AM.', 2, true),\n  ('Enrollment deadline', 'Submit forms by Friday.', 3, true),\n  ('Lost umbrella', 'Found near Room 102.', NULL, false);","lang":"sql"},{"k":"callout","t":"The last notice has no category on purpose. You will need it in Step 8."}],"id":"insert-sample-data"},{"title":"Read with SELECT, WHERE and ORDER BY","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"SELECT * FROM notices;\nSELECT id, title FROM notices WHERE pinned = true ORDER BY created_at DESC;\nSELECT title FROM notices WHERE title ILIKE '%library%';","lang":"sql"},{"k":"list","items":[[["Write one more query of your own: the three newest notices, using ORDER BY and LIMIT 3.",false]]]}],"id":"read-with-select-where-and-order-by"},{"title":"Update and delete, then break a rule","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"code","t":"UPDATE notices SET pinned = false WHERE title = 'Foundation Day program';\nDELETE FROM notices WHERE title = 'Lost umbrella';\n\n-- These two should fail. Read each error message.\nINSERT INTO categories (name) VALUES ('urgent');\nINSERT INTO notices (title, message, category_id) VALUES ('Bad', 'No such category', 99);","lang":"sql"},{"k":"list","items":[[["Which constraint rejected each statement? Write the answer next to the query in queries.sql as a comment.",false]]]},{"k":"callout","t":"Put the Lost umbrella notice back with its INSERT before Step 8."}],"id":"update-and-delete-then-break-a-rule"},{"title":"Join notices to categories","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"code","t":"SELECT n.title, c.name AS category\nFROM notices n\nJOIN categories c ON c.id = n.category_id;\n\nSELECT n.title, c.name AS category\nFROM notices n\nLEFT JOIN categories c ON c.id = n.category_id;","lang":"sql"},{"k":"list","items":[[["Compare the two results. Which notice appears only in the second, and why? Take a screenshot of the second result.",false]]]}],"id":"join-notices-to-categories"},{"title":"Count notices per category","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"code","t":"SELECT c.name, COUNT(n.id) AS total\nFROM categories c\nLEFT JOIN notices n ON n.category_id = c.id\nGROUP BY c.name\nORDER BY total DESC;","lang":"sql"}],"id":"count-notices-per-category"},{"title":"Save your queries","tag":"STEP 10","kind":"step","step":10,"blocks":[{"k":"list","items":[[["Copy every working statement into a file named queries.sql, in the order you ran them, with a short comment above each.",false]],[["Re-run the whole file on a fresh database to prove it works: DROP DATABASE notices_db; then repeat from Step 2 using only your file.",false]]]}],"id":"save-your-queries"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["PostgreSQL is installed and you can connect with psql or pgAdmin.",false]],[["The categories and notices tables exist, and \\d notices shows the foreign key.",false]],[["You have inserted, selected, updated and deleted rows, and seen two constraint errors.",false]],[["Your queries.sql contains the CRUD, join and count queries and runs from top to bottom.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Write a query that lists the categories that have no notices at all. Hint: start from categories, LEFT JOIN notices, and keep the rows where the notice id IS NULL."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":null,"slideCount":null,"pptx":null,"syllabus":{"label":"Week 10","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Explain the relational model: tables, rows, primary keys and foreign keys.","Install PostgreSQL and connect with psql or pgAdmin.","Create tables with data types and constraints using SQL.","Write SELECT, INSERT, UPDATE and DELETE queries with filtering, sorting and joins."],"topics":{"lecture":["Relational model: tables, rows, keys and relationships","Installing PostgreSQL; psql and pgAdmin","Creating tables, data types and constraints","SELECT, WHERE, ORDER BY, INSERT, UPDATE and DELETE","Joins and aggregate basics"],"laboratory":["Install PostgreSQL 14+ and connect with psql or pgAdmin","Design and create the notices and categories tables","Write CRUD and join queries against sample data"]},"methods":["Lecture with live coding","Hands-on SQL practice","Think-pair-share (document versus relational data)","Individual lab practice"],"resources":["PostgreSQL 14+; psql or pgAdmin; VS Code","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 10 materials","PostgreSQL Global Development Group (n.d.), PostgreSQL documentation (SQL tutorial)"],"assessment":["Quiz 7: relational model and SQL","Lab 10 output: notices database with CRUD and join queries","Recitation: compare document and relational data models"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Relational databases are among the most requested skills in software job postings."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"Relational databases underpin most locally built information systems."}]}},{"week":11,"title":"Your API on PostgreSQL","focus":"move the notices API from MongoDB to PostgreSQL","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Move your Week 8 notices API from MongoDB to PostgreSQL using raw SQL with pg, and prove every route still behaves the same.",false]],[["Deliverable. ",true],["Lab 11 output: the notices API running on PostgreSQL (Project Checkpoint 3), with your Postman collection passing.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: move the API to PostgreSQL","tag":null,"kind":"divider","sub":"Work in a copy of your Week 8 project so the MongoDB version stays safe.","id":"step-by-step-guide-move-the-api-to-postgresql"},{"title":"Copy the project and install pg","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"cp -r notices-api notices-api-pg\ncd notices-api-pg\nnpm install pg dotenv","lang":"bash"},{"k":"callout","t":"On Windows without cp, copy the folder in File Explorer. Make sure the notices_db database and tables from Week 10 still exist."}],"id":"copy-the-project-and-install-pg"},{"title":"Add the connection file","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"# .env\nDATABASE_URL=postgres://postgres:YOUR_PASSWORD@localhost:5432/notices_db","lang":"text"},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst { Pool } = require(\"pg\");\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\nmodule.exports = { query: (text, params) => pool.query(text, params) };","lang":"javascript"},{"k":"code","t":"// temporary check, run with: node check.js\nconst db = require(\"./db\");\ndb.query(\"SELECT now()\").then((r) => { console.log(r.rows[0]); process.exit(); });","lang":"javascript"},{"k":"callout","t":"You should see the current time. If you see a password error, fix .env. Add .env to .gitignore."}],"id":"add-the-connection-file"},{"title":"List all notices","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"exports.getAll = asyncHandler(async (req, res) => {\n  const { rows } = await db.query(\"SELECT * FROM notices ORDER BY created_at DESC\");\n  res.json(rows);\n});","lang":"javascript"},{"k":"list","items":[[["Test GET /api/notices in Postman. You should get the rows you inserted in Week 10.",false]]]}],"id":"list-all-notices"},{"title":"Get one notice","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"exports.getOne = asyncHandler(async (req, res) => {\n  const { rows } = await db.query(\"SELECT * FROM notices WHERE id = $1\", [req.params.id]);\n  if (rows.length === 0) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(rows[0]);\n});","lang":"javascript"}],"id":"get-one-notice"},{"title":"Create a notice","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"code","t":"exports.create = asyncHandler(async (req, res) => {\n  const { title, message, category_id } = req.body;\n  const { rows } = await db.query(\n    \"INSERT INTO notices (title, message, category_id) VALUES ($1, $2, $3) RETURNING *\",\n    [title, message, category_id || null]\n  );\n  res.status(201).json(rows[0]);\n});","lang":"javascript"},{"k":"list","items":[[["Keep your validation middleware from Week 7. Test a good request (201) and one with no title (400).",false]]]}],"id":"create-a-notice"},{"title":"Update and delete","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"exports.update = asyncHandler(async (req, res) => {\n  const { title, message, pinned } = req.body;\n  const { rows } = await db.query(\n    \"UPDATE notices SET title = $1, message = $2, pinned = $3 WHERE id = $4 RETURNING *\",\n    [title, message, pinned, req.params.id]\n  );\n  if (rows.length === 0) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(rows[0]);\n});\n\nexports.remove = asyncHandler(async (req, res) => {\n  const result = await db.query(\"DELETE FROM notices WHERE id = $1\", [req.params.id]);\n  if (result.rowCount === 0) return res.status(404).json({ error: \"Notice not found.\" });\n  res.status(204).end();\n});","lang":"javascript"}],"id":"update-and-delete"},{"title":"Teach the error handler the PostgreSQL codes","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Add the codes from the table below to your central errorHandler, then request GET /api/notices/abc and expect a 400, not a 500.",false]]]}],"id":"teach-the-error-handler-the-postgresql-codes"},{"title":"Run your Postman collection and compare","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Run the Week 6 collection against the new server.",false]],[["For every request, compare the status code with the Mongoose version. Write down any difference and the reason for it.",false]]]},{"k":"callout","t":"Typical differences: ids are numbers instead of ObjectIds, and the date field is now created_at."}],"id":"run-your-postman-collection-and-compare"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["No route uses Mongoose any more, and every query uses placeholders ($1, $2).",false]],[["All five routes work, and the bad-case requests return 400 or 404 instead of 500.",false]],[["Your Postman collection passes with only small changes.",false]],[["Data survives a server restart, and .env is not committed.",false]]]}],"id":"you-are-done-when"},{"title":"Why placeholders matter","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Imagine a careless controller that glues the user's text into the SQL:",false]]]},{"k":"code","t":"// NEVER do this\nconst { search } = req.query;\nconst sql = \"SELECT * FROM notices WHERE title ILIKE '%\" + search + \"%'\";\nawait db.query(sql);","lang":"javascript"},{"k":"callout","t":"A normal visitor sends ?search=library and the SQL becomes ... ILIKE '%library%', which is fine. An attacker sends ?search=x%'; DELETE FROM notices; -- and the SQL text becomes:"},{"k":"code","t":"SELECT * FROM notices WHERE title ILIKE '%x%'; DELETE FROM notices; --%'","lang":"text"},{"k":"callout","t":"The database now sees a second statement and deletes every notice. This attack is called SQL injection. With a placeholder the values travel separately, so the same input is treated only as text to search for:"},{"k":"code","t":"await db.query(\"SELECT * FROM notices WHERE title ILIKE $1\", [`%${search}%`]);\n// searches for the literal text  x%'; DELETE FROM notices; --   and finds nothing","lang":"javascript"},{"k":"callout","t":"And this is what db.query hands back, so you know why the controllers read rows:"},{"k":"code","t":"const result = await db.query(\"SELECT id, title FROM notices WHERE id = $1\", [2]);\nconsole.log(result.rows);      // [ { id: 2, title: 'Enrollment reminder' } ]\nconsole.log(result.rowCount);  // 1\n// for an id that does not exist: rows is [] and rowCount is 0, so answer 404","lang":"javascript"},{"k":"callout","t":"PostgreSQL reports its own errors with a short code. Teach your central error handler the ones below, and the same safety net you built in Week 8 keeps working."},{"k":"table","head":["Code","Meaning","Reply"],"rows":[["22P02","Bad value for the type, such as the id abc","400"],["23502","A NOT NULL column was left empty","400"],["23514","A CHECK rule failed","400"],["23505","A UNIQUE rule failed, such as a duplicate email","409"]]}],"id":"why-placeholders-matter"},{"title":"A database error becoming the right answer","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A client sends GET /api/notices/abc.",false]],[["The table's id column is a number, so PostgreSQL refuses to compare it with the text abc.",false]]]},{"k":"table","head":["Step","What happens"],"rows":[["1","The controller runs SELECT ... WHERE id = $1 with the value \"abc\""],["2","PostgreSQL throws an error with err.code === \"22P02\" (invalid text representation)"],["3","asyncHandler catches it and calls next(err)"],["4","The error handler sees code 22P02 in the table above and answers 400 { \"error\": \"Invalid id.\" }"]]},{"k":"list","items":[[["Now compare a registration with an email that already exists: the UNIQUE rule makes PostgreSQL throw 23505, and the same handler answers 409.",false]],[["The controllers never need a special try/catch; the database reports, asyncHandler forwards, and one handler decides the status code.",false]]]}],"extra":["A code that is not in your table falls through to the final 500 Something went wrong, and the real error is printed in the server terminal."],"id":"a-database-error-becoming-the-right-answer"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a search route: GET /api/notices?search=library. Use ILIKE with a placeholder, and test it with the SQL injection text from the worked example to prove it is safe."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":null,"slideCount":null,"pptx":null,"syllabus":{"label":"Week 11","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Connect an Express application to PostgreSQL using the pg library and a connection pool.","Write parameterized SQL queries that prevent SQL injection.","Implement CRUD routes backed by raw SQL.","Migrate the notices API from MongoDB to PostgreSQL."],"topics":{"lecture":["Express with PostgreSQL using the node-postgres (pg) library","Connection pool versus single client","Parameterized queries and SQL injection prevention","Mapping rows to JSON responses and handling database errors","Migrating from Mongoose to raw SQL"],"laboratory":["Connect the notices API to PostgreSQL with pg","Move the notices API from MongoDB to PostgreSQL using raw SQL","Test every route with Postman and compare with the Mongoose version"]},"methods":["Lecture with live coding","Migration lab (MongoDB to PostgreSQL)","Debugging clinic","Individual lab practice"],"resources":["Express; PostgreSQL; node-postgres (pg); Postman","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 11 materials","node-postgres (n.d.), node-postgres documentation","PostgreSQL Global Development Group (n.d.), PostgreSQL documentation","OpenJS Foundation (n.d.), Express documentation"],"assessment":["Lab 11 output: notices API running on PostgreSQL","Project Checkpoint 3: Notices API on PostgreSQL","Short quiz: parameterized queries and SQL injection"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Back-end data-access skills prepare students for entry-level full-stack roles."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"Migrating between database technologies mirrors real modernization of industry systems."}]}},{"week":12,"title":"Static components; static notices page","focus":"build static components","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build the notice interface from components, using hard-coded data. There is no server in this lab, so you can focus on structure and props.",false]],[["Deliverable. ",true],["A React project with at least five components (Header, NoticeCard, NoticeList, EmptyState, Footer), a list rendered with map and keys, and a screenshot.",false]]]}],"extra":["Browser tip: if the page goes blank, open the Console. The error message usually names the file and line."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: static React components","tag":null,"kind":"divider","sub":"Follow the steps in order and check the page in the browser after every step.","id":"step-by-step-guide-static-react-components"},{"title":"Create the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"npm create vite@latest notices-ui -- --template react\ncd notices-ui\nnpm install\nnpm run dev","lang":"bash"},{"k":"callout","t":"Open the address Vite prints (usually http://localhost:5173). You should see the Vite and React starter page. Now open src/App.jsx, delete everything inside it and write only this, then delete src/App.css contents and the logo imports:"},{"k":"code","t":"export default function App() {\n  return <h1>Campus Notices</h1>;\n}","lang":"javascript"},{"k":"callout","t":"The page should now show only the heading. If it is blank, open the Console and read the first red line."}],"id":"create-the-project"},{"title":"Write Header and Footer","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Create a folder src/components, then two files:",false]]]},{"k":"code","t":"// src/components/Header.jsx\nexport default function Header() {\n  return (\n    <header>\n      <h1>Campus Notices Board</h1>\n      <p>Announcements for every student</p>\n    </header>\n  );\n}","lang":"javascript"},{"k":"code","t":"// src/components/Footer.jsx\nexport default function Footer() {\n  return <footer>DMMMSU Campus Notices, 2026</footer>;\n}","lang":"javascript"},{"k":"callout","t":"Use them in App.jsx:"},{"k":"code","t":"import Header from \"./components/Header\";\nimport Footer from \"./components/Footer\";\n\nexport default function App() {\n  return (","lang":"javascript"},{"k":"code","t":"    <>\n      <Header />\n      <main>Notices will go here</main>\n      <Footer />\n    </>\n  );\n}","lang":"xml"},{"k":"callout","t":"You should see the header, the placeholder text and the footer in that order. Component names must start with a capital letter, or React treats them as HTML tags."}],"id":"write-header-and-footer"},{"title":"Write NoticeCard with props","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"// src/components/NoticeCard.jsx\nexport default function NoticeCard({ title, message, createdAt, pinned }) {\n  return (\n    <article className=\"notice\">\n      <h2>{pinned && \"📌 \"}{title}</h2>\n      <p>{message}</p>\n      <small>{new Date(createdAt).toLocaleDateString()}</small>\n    </article>\n  );\n}","lang":"javascript"},{"k":"callout","t":"Test it by temporarily putting one card in App.jsx: <NoticeCard title=\"Library hours\" message=\"Open until 9 PM\" createdAt=\"2026-10-12\" pinned={true} />. You should see one card with the pin. Change pinned to {false} and the pin disappears. Props flow one way, down from the parent."}],"id":"write-noticecard-with-props"},{"title":"Write NoticeList and EmptyState","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["First the data, at the top of App.jsx (outside the component):",false]]]},{"k":"code","t":"const notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM.\", createdAt: \"2026-10-12\", pinned: true, category: \"academic\" },\n  { id: 2, title: \"Programming contest\", message: \"Sign up at the CCS office.\", createdAt: \"2026-10-13\", pinned: false, category: \"events\" },\n  { id: 3, title: \"Enrollment reminder\", message: \"Last day to add or drop is Friday.\", createdAt: \"2026-10-14\", pinned: false, category: \"urgent\" },\n];","lang":"javascript"},{"k":"code","t":"// src/components/EmptyState.jsx\nexport default function EmptyState() {\n  return <p>No notices yet. Check back later.</p>;\n}","lang":"javascript"},{"k":"code","t":"// src/components/NoticeList.jsx\nimport NoticeCard from \"./NoticeCard\";\nimport EmptyState from \"./EmptyState\";\n\nexport default function NoticeList({ notices }) {\n  if (notices.length === 0) return <EmptyState />;\n  return (\n    <section>","lang":"javascript"},{"k":"code","t":"      {notices.map((n) => (\n        <NoticeCard key={n.id} {...n} />\n      ))}\n    </section>\n  );\n}","lang":"javascript"},{"k":"callout","t":"Replace the placeholder in App.jsx with <NoticeList notices={notices} />. You should see three cards. Open the Console: there must be no warning about keys. The key lets React tell items apart, and it must be a stable id, not the array index."}],"id":"write-noticelist-and-emptystate"},{"title":"Add category labels","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In NoticeCard, add category to the props and show <span className={\"label \" + category}>{category}</span> under the title.",false]],[["In App.css give .label.academic, .label.events and .label.urgent three different background colours.",false]],[["Each card should now show a coloured label.",false]]]}],"extra":["(Skip this step if you are behind.)"],"id":"add-category-labels"},{"title":"Style the page","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Write your styles in src/App.css and import it at the top of App.jsx with import \"./App.css\";.",false]],[["Give .notice a border, padding and a margin, and centre main with max-width: 700px; margin: 0 auto;.",false]]]}],"id":"style-the-page"},{"title":"Test the empty state","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["In App.jsx change the call to <NoticeList notices={[]} />.",false]],[["You should see \"No notices yet.\" Change it back and take your screenshot.",false]]]}],"id":"test-the-empty-state"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The page has Header, NoticeCard, NoticeList, EmptyState and Footer components, each in its own file.",false]],[["The list uses map with a key, and the Console shows no warnings.",false]],[["The empty state appears when the array is empty.",false]],[["You have the screenshot, and you can explain in one sentence what a prop is.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Build a filter bar that is purely visual: render three category buttons and highlight the one whose name is passed in as a prop called active. In Week 13 you will make it interactive."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_12_Laboratory_React_components_and_props.pptx","slideCount":19,"pptx":"downloads/laboratory/Week_12_Laboratory_React_components_and_props.pptx","syllabus":{"label":"Week 12","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Explain what React is and how a component tree is rendered.","Write JSX and function components.","Pass data with props and compose components.","Render lists with keys."],"topics":{"lecture":["Setting up a React project with Vite","JSX and function components","Props and component composition","Rendering lists and keys"],"laboratory":["Create a React project with Vite","Build static NoticeCard and NoticeList components","Render a list of notices from sample data using props"]},"methods":["Lecture with live coding","Component-building lab","Think-pair-share (one-way data flow)","Peer code review"],"resources":["Node.js; React; Vite; VS Code","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 12 materials","Meta Open Source (n.d.), React documentation","Banks & Porcello (2020), chapters on JSX and components"],"assessment":["Quiz 8: JSX, components and props","Lab 12 output: static notices page built from components","Recitation: explain props and one-way data flow"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"React is among the most requested skills in software job postings."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"Component-based interfaces are a staple of locally built digital systems."}]}},{"week":13,"title":"Notice form","focus":"notice form with local state","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Make your static interface from Week 12 interactive, using only local state. There is still no server.",false]],[["Deliverable. ",true],["A page where the user can post a notice, search the list, and delete a notice, with form validation messages.",false]]]}],"extra":["When your page does not update, ask: did I call the setter, and did I give it a new array or object?"],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: notice form with local state","tag":null,"kind":"divider","sub":"Work in your Week 12 project.","id":"step-by-step-guide-notice-form-with-local-state"},{"title":"Move the notices into state","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["In App.jsx, delete the top-level notices constant and keep the data as the starting value:",false]]]},{"k":"code","t":"import { useState } from \"react\";\n\nconst initialNotices = [ /* your three notices from Week 12 */ ];\n\nexport default function App() {\n  const [notices, setNotices] = useState(initialNotices);\n  // ...\n  return (\n    <>","lang":"javascript"},{"k":"code","t":"      <Header />\n      <main><NoticeList notices={notices} /></main>\n      <Footer />\n    </>\n  );\n}","lang":"xml"},{"k":"callout","t":"The page should look exactly as it did before. If it does, state is wired correctly."}],"id":"move-the-notices-into-state"},{"title":"Build NoticeForm with controlled inputs","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"// src/components/NoticeForm.jsx\nimport { useState } from \"react\";\n\nexport default function NoticeForm({ onAdd }) {\n  const [title, setTitle] = useState(\"\");\n  const [message, setMessage] = useState(\"\");\n\n  function handleSubmit(e) {\n    e.preventDefault(); // stop the page from reloading\n    onAdd({ title, message });\n    setTitle(\"\");\n    setMessage(\"\");\n  }","lang":"javascript"},{"k":"code","t":"  return (\n    <form onSubmit={handleSubmit}>\n      <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder=\"Title\" />\n      <textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder=\"Message\" />\n      <button type=\"submit\">Post notice</button>\n    </form>\n  );\n}","lang":"xml"},{"k":"callout","t":"In App.jsx add the handler and the form:"},{"k":"code","t":"function handleAdd({ title, message }) {\n  const notice = {\n    id: Date.now(), // temporary id; the server gives the real one in Week 15\n    title,\n    message,\n    createdAt: new Date().toISOString(),\n    pinned: false,\n    category: \"general\",\n  };\n  setNotices([notice, ...notices]); // a NEW array, newest first\n}","lang":"javascript"},{"k":"callout","t":"Put <NoticeForm onAdd={handleAdd} /> above the list. Type a title and message and press the button. You should see the new card at the top and the form clear. Typing in the boxes should feel normal, because every keystroke updates state."}],"id":"build-noticeform-with-controlled-inputs"},{"title":"Add validation messages","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["In NoticeForm, add const [error, setError] = useState(\"\"); and change handleSubmit:",false]]]},{"k":"code","t":"function handleSubmit(e) {\n  e.preventDefault();\n  if (title.trim() === \"\" || message.trim() === \"\") {\n    setError(\"Title and message are both required.\");\n    return;\n  }\n  setError(\"\");\n  onAdd({ title: title.trim(), message: message.trim() });\n  setTitle(\"\");","lang":"javascript"},{"k":"code","t":"  setMessage(\"\");\n}","lang":"javascript"},{"k":"callout","t":"Show it with {error && <p role=\"alert\">{error}</p>} above the button. Submit an empty form and you should see the message and no new card. Submit a good one and the message disappears."}],"id":"add-validation-messages"},{"title":"Add delete","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["In App.jsx:",false]]]},{"k":"code","t":"function handleDelete(id) {\n  setNotices(notices.filter((n) => n.id !== id));\n}","lang":"javascript"},{"k":"list","items":[[["Pass it down: <NoticeList notices={notices} onDelete={handleDelete} />.",false]]]},{"k":"list","items":[[["In NoticeList accept onDelete and give each card onDelete={() => onDelete(n.id)}.",false]],[["In NoticeCard accept onDelete and add <button onClick={onDelete}>Delete</button>.",false]]]}],"extra":["Click Delete on a card and it should vanish. Notice the data flows down as props and the event flows up through a function."],"id":"add-delete"},{"title":"Add search as derived data","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In App.jsx add const [search, setSearch] = useState(\"\"); and compute the list to show.",false]],[["Do not store the filtered list in state:",false]]]},{"k":"code","t":"const visible = notices.filter((n) =>\n  n.title.toLowerCase().includes(search.toLowerCase())\n);","lang":"javascript"},{"k":"callout","t":"Add <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder=\"Search notices\" /> and pass visible to NoticeList. Type \"lib\" and only matching cards remain. Clear the box and all return. Delete a card while searching and check it still works."}],"id":"add-search-as-derived-data"},{"title":"Add a character counter","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["In NoticeForm, below the textarea, show <small>{message.length} / 500</small> and add maxLength={500} to the textarea.",false]],[["The number should change as you type.",false]],[["(Skip this if you are behind.)",false]]]}],"id":"add-a-character-counter"},{"title":"Test the edge cases","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"table","head":["Try this","You should see"],"rows":[["Submit with only spaces","The validation message"],["Paste 600 characters in the message","Typing stops at 500"],["Delete every notice","The empty state"],["Search for text that matches nothing","The empty state"],["Add two notices quickly","Both appear, newest first"]]},{"k":"list","items":[[["Show your instructor before you leave the lab.",false]]]}],"id":"test-the-edge-cases"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["notices lives in state and the form adds to it using a new array.",false]],[["Empty and space-only input shows a message and adds nothing.",false]],[["Delete and search both work, and search is derived, not stored.",false]],[["You can explain why setNotices([notice, ...notices]) works and notices.push(notice) does not.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add an edit mode: clicking \"Edit\" on a card turns its title and message into inputs. \"Save\" updates the item with map and a spread, and \"Cancel\" restores the original."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_13_Laboratory_React_state_events_and_controlled_forms.pptx","slideCount":20,"pptx":"downloads/laboratory/Week_13_Laboratory_React_state_events_and_controlled_forms.pptx","syllabus":{"label":"Week 13","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Manage component state with useState.","Handle user events in components.","Build controlled forms with validation messages.","Lift state up to share data between components."],"topics":{"lecture":["useState and re-rendering","Event handling","Controlled inputs and form submission","Lifting state up"],"laboratory":["Build a notice form with local state","Add and remove notices in component state","Show validation messages on the form"]},"methods":["Lecture with live coding","Component-building lab","Think-pair-share (state flow)","Peer code review"],"resources":["Node.js; React; Vite; VS Code","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 13 materials","Meta Open Source (n.d.), React documentation","Banks & Porcello (2020), chapters on state and forms"],"assessment":["Short quiz: state, events and controlled forms","Lab 13 output: notice form with local state","Recitation: explain controlled inputs"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Interactive interface skills are required in entry-level front-end and full-stack roles."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"Interactive forms are the entry point of most locally built digital services."}]}},{"week":14,"title":"Fetch a list from your API","focus":"fetch a list from an API","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Replace the hard-coded notices in your Week 13 page with real data from your own API, which you built on PostgreSQL in Week 11.",false]],[["Deliverable. ",true],["A page that loads notices from your own server, with working loading, error and empty states, a Refresh button, and a screenshot of each state.",false]]]}],"extra":["To see the loading state, add a temporary delay on the server, for example await new Promise((r) => setTimeout(r, 2000)) in the route. Remove it afterwards."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: fetch notices from your API","tag":null,"kind":"divider","sub":"This guide is the React half of the lab.","id":"step-by-step-guide-fetch-notices-from-your-api"},{"title":"Check the API in Postman","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["GET http://localhost:3001/api/notices must return 200 and a JSON array.",false]],[["Each notice should have id, title, message, createdAt.",false]],[["If it does not, fix the server before touching React.",false]]]}],"id":"check-the-api-in-postman"},{"title":"Let Vite forward /api to your server","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["In vite.config.js add a proxy so the browser sees one origin and CORS does not get in the way:",false]]]},{"k":"code","t":"import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n  server: { proxy: { \"/api\": \"http://localhost:3001\" } },\n});","lang":"javascript"},{"k":"callout","t":"Stop and restart npm run dev in the client (the config is read only at start). You should be able to open http://localhost:5173/api/notices and see the same JSON as in Postman."}],"id":"let-vite-forward-api-to-your-server"},{"title":"Add three pieces of state and fetch in useEffect","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["In App.jsx:",false]]]},{"k":"code","t":"import { useState, useEffect } from \"react\";\n\nconst [notices, setNotices] = useState([]);\nconst [loading, setLoading] = useState(true);\nconst [error, setError] = useState(null);\n\nuseEffect(() => {\n  fetch(\"/api/notices\")\n    .then((res) => {\n      if (!res.ok) throw new Error(`Server answered ${res.status}`);\n      return res.json();","lang":"javascript"},{"k":"code","t":"    })\n    .then((data) => setNotices(data))\n    .catch((err) => setError(err.message))\n    .finally(() => setLoading(false));\n}, []); // the empty array means: run once, after the first render","lang":"javascript"},{"k":"callout","t":"Show the data with <NoticeList notices={notices} />. You should see your database rows as cards. In the server terminal you should see the request arrive once. If it arrives in an endless loop, you forgot the []."}],"id":"add-three-pieces-of-state-and-fetch-in-useeffect"},{"title":"Render loading, error and empty states","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Above the main return add early returns:",false]]]},{"k":"code","t":"if (loading) return <p>Loading notices...</p>;\nif (error) return <p role=\"alert\">Could not load notices: {error}</p>;","lang":"xml"},{"k":"callout","t":"NoticeList already shows EmptyState for an empty array. res.ok matters because fetch does not throw on a 404 or 500; without that line a failed request would look like an empty list."}],"id":"render-loading-error-and-empty-states"},{"title":"Fix the keys and the date","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Make sure NoticeList uses key={n.id} (the real database id), and that the card shows new Date(createdAt).toLocaleString().",false]],[["If the date shows \"Invalid Date\", look at the JSON in Postman: your server must send createdAt, not created_at (use created_at AS \"createdAt\" in the SQL).",false]]]}],"id":"fix-the-keys-and-the-date"},{"title":"Add a Refresh button","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Move the fetch into a function and call it from both places:",false]]]},{"k":"code","t":"const loadNotices = useCallback(() => {\n  setLoading(true);\n  setError(null);\n  fetch(\"/api/notices\")\n    .then((res) => { if (!res.ok) throw new Error(`Server answered ${res.status}`); return res.json(); })\n    .then(setNotices)\n    .catch((err) => setError(err.message))\n    .finally(() => setLoading(false));\n}, []);","lang":"javascript"},{"k":"code","t":"useEffect(() => { loadNotices(); }, [loadNotices]);","lang":"javascript"},{"k":"callout","t":"(Import useCallback from react.) Add <button onClick={loadNotices}>Refresh</button>. Insert a row in psql, click Refresh, and the new row should appear without reloading the page."}],"id":"add-a-refresh-button"},{"title":"Reproduce each state on purpose and take a screenshot of each","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"table","head":["To get this state","Do this"],"rows":[["Loading","Add await new Promise((r) => setTimeout(r, 2000)) to the server route, reload, then remove it"],["Error","Stop the server and click Refresh"],["Empty","Run DELETE FROM notices; in psql, then Refresh"]]}],"id":"reproduce-each-state-on-purpose-and-take-a-scree"},{"title":"Add a search box (stretch)","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Add search state and send it to the server with fetch(\"/api/notices?search=\" + encodeURIComponent(search)).",false]],[["On the server, in getNotices, add the filter:",false]]]},{"k":"code","t":"const { search } = req.query;\nconst { rows } = search\n  ? await db.query(\n      `SELECT id, title, message, created_at AS \"createdAt\" FROM notices WHERE title ILIKE $1 ORDER BY created_at DESC`,\n      [`%${search}%`]\n    )","lang":"javascript"},{"k":"code","t":"  : await db.query(\n      `SELECT id, title, message, created_at AS \"createdAt\" FROM notices ORDER BY created_at DESC`\n    );\nres.json(rows);","lang":"javascript"},{"k":"callout","t":"The $1 placeholder keeps the user's text out of the SQL itself, so it cannot inject SQL."}],"id":"add-a-search-box-stretch"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The page shows rows from PostgreSQL through your own API.",false]],[["Loading, error and empty states each appear when triggered, and you have three screenshots.",false]],[["The server logs one request per page load, not an endless loop.",false]],[["You can explain why fetch needs the res.ok check.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Replace the ignore flag with an AbortController. Pass its signal to fetch, abort it in the cleanup function, and ignore the resulting AbortError so it does not show as a user-facing error."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_14_Laboratory_React_effects_fetching_loading_and_error.pptx","slideCount":24,"pptx":"downloads/laboratory/Week_14_Laboratory_React_effects_fetching_loading_and_error.pptx","syllabus":{"label":"Week 14","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Use effects to fetch data in React components.","Explain dependency arrays and effect cleanup.","Display loading, error and empty states.","Render data returned by the Express/PostgreSQL API."],"topics":{"lecture":["useEffect and dependency arrays","Fetching data from an API in React","Loading, error and empty states","Cleaning up effects"],"laboratory":["Fetch and render a list of notices from the PostgreSQL API","Show loading, error and empty states","Handle failed requests gracefully"]},"methods":["Lecture with live coding","Debugging clinic","Individual lab practice","Peer code review"],"resources":["React; Vite; Express; browser Developer Tools","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 14 materials","Meta Open Source (n.d.), React documentation","Mozilla Developer Network (n.d.), Fetch API guide"],"assessment":["Quiz 9: effects and data fetching","Lab 14 output: notices fetched from the API with loading and error states"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Data-driven interfaces prepare students for entry-level full-stack roles."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"Data-driven interfaces are staples of locally built digital systems."}]}},{"week":15,"title":"Connecting React to your API","focus":"Campus Notices Board","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build the full-stack Campus Notices Board: an Express API that stores notices and a React page that lists them and posts new ones. This is the culminating lab for the first half of the course.",false]],[["Deliverable. ",true],["A working app plus a Postman screenshot (one success and one 400), a Network-tab screenshot of your POST request, and a completed exit ticket.",false]]]}],"extra":["It is run in three tracks so every student is stretched without being stuck. Your instructor will share the lab handout, the starter repository and the rubric."],"id":"goal-and-deliverable"},{"title":"Where the data lives","tag":"LAB","kind":"brief","blocks":[{"k":"list","items":[[["Tracks A and B keep notices in an array, exactly as in the handout, so the lab stays about the request lifecycle.",false]]]},{"k":"table","head":["Track","What you receive","What you do"],"rows":[["A: Guided","Working GET route and fetch, with blanks in the POST route and the POST fetch","Fill in the blanks, test, then take the stretch step: validation, then loading and error messages"],["B: Standard","The project wiring and TODO comments only","Build both routes with validation, then the React page with loading, empty and error states"],["C: Extension","A layered PostgreSQL project (routes, controllers, db.js, middleware, tests) with TODOs","Build the layered API on PostgreSQL and the React page, then add at least two extensions: full CRUD, tests, search and filter, or optimistic UI"]]},{"k":"table","head":["Segment","Minutes"],"rows":[["Setup and orientation","15"],["Build the API","45"],["Test the API in Postman","15"],["Break","10"],["Build the React client","60"],["Checkpoint demo: show the Network tab and explain one request","20"],["Exit ticket and reflection","15"]]},{"k":"list","items":[[["Test every server step in Postman before you touch React.",false]]]},{"k":"list","items":[[["You may move between tracks at any time.",false]],[["Moving up when it feels easy is encouraged, and moving down to get unstuck is never a penalty.",false]]]}],"extra":["Track C builds on PostgreSQL from the start: the starter gives you db.js and schema.sql, you write the controllers with the parameterized-query pattern from Week 11, and the board runs as a true PERN app. If you finish early in Track A or B, moving your notices into the PostgreSQL table is the best next step."],"id":"where-the-data-lives"},{"title":"A step-by-step path for every track","tag":"LAB","kind":"brief","blocks":[{"k":"list","items":[[["The handout gives each track its own numbered guide, with what to do, what you should see, and a checkpoint after each part.",false]],[["The path is the same shape in all three:",false]],[["Start the server and see it respond (Track A reads a finished GET route; Tracks B and C write it).",false]],[["Build the POST route with validation (Track A fills in the blanks first and adds validation as a stretch).",false]]]},{"k":"list","items":[[["Test every server route in Postman and write down each status code. Take a screenshot of one 201 and one 400. Checkpoint 1.",false]],[["Build or finish the React page: state, loading on first render, the form, and the list.",false]],[["Break it on purpose: stop the server and confirm the page explains the problem instead of going blank.",false]],[["Open the Network tab, find your POST request, and explain its status code and payload. Checkpoint 2.",false]]]},{"k":"list","items":[[["Track C only: add at least two extensions (full CRUD, tests, search and filter, or optimistic UI).",false]]]}],"id":"a-step-by-step-path-for-every-track"},{"title":"Step-by-step guide: Week 15 checkpoints","tag":null,"kind":"divider","sub":"The handout has the full numbered guide for your track.","id":"step-by-step-guide-week-13-checkpoints"},{"title":"Set up (15 minutes)","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Pick your track, copy the starter for it, and run npm install in both the server and client folders.",false]],[["Create .env from .env.example (Track C: also run db/schema.sql in your campus_notices database).",false]],[["Start the server with npm run dev.",false]]]}],"extra":["Step 1 (15 minutes). You should see API on http://localhost:3001, and GET /api/health (or GET /api/notices) should answer in Postman."],"id":"set-up-15-minutes"},{"title":"Build the API (45 minutes)","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Write the routes in the order GET, then POST with validation.",false]],[["After each one, test it in Postman.",false]],[["Track C writes them as controllers using db.query with $1 placeholders, RETURNING, and created_at AS \"createdAt\".",false]]]}],"extra":["Step 2 (45 minutes)."],"id":"build-the-api-45-minutes"},{"title":"Test every server route (15 minutes)","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Send a good POST (201), an empty title (400) and a missing body (400).",false]],[["Write down every status code and take your screenshot of one 201 and one 400.",false]],[["Checkpoint 1: do not open React until this passes.",false]]]}],"extra":["Step 3 (15 minutes)."],"id":"test-every-server-route-15-minutes"},{"title":"Build the client (60 minutes)","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["State first, then useEffect with loading and error states, then the form that POSTs, then the list.",false]],[["Test in the browser after each part.",false]]]}],"extra":["Step 4 (60 minutes)."],"id":"build-the-client-60-minutes"},{"title":"Checkpoint demo (20 minutes)","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Open the Network tab, send a POST from the page, and explain its method, URL, payload and status code to your instructor.",false]],[["Checkpoint 2.",false]]]}],"extra":["Step 5 (20 minutes)."],"id":"checkpoint-demo-20-minutes"},{"title":"Exit ticket (15 minutes)","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Complete the exit ticket and reflection honestly.",false]]]}],"extra":["Step 6 (15 minutes)."],"id":"exit-ticket-15-minutes"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The API passes the Postman checks with correct status codes.",false]],[["The page shows loading, empty and error states and can post a notice.",false]],[["You have both screenshots and your exit ticket.",false]],[["Track C: at least two extensions are working.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add optimistic updates: show the new notice in the list instantly with a temporary label, then replace it with the server's version when the response arrives. If the server rejects it, remove it and show the error."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_15_Laboratory_Connecting_React_to_your_API.pptx","slideCount":17,"pptx":"downloads/laboratory/Week_15_Laboratory_Connecting_React_to_your_API.pptx","syllabus":{"label":"Week 15","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Configure a development proxy and explain CORS.","Trace a request through React, Express and PostgreSQL.","Integrate a React front end with a back-end API.","Debug integration problems using browser and server tools."],"topics":{"lecture":["Development proxy and CORS","The full request lifecycle: React, Express, PostgreSQL","Integrating front end and back end","Debugging with the Network tab and server logs"],"laboratory":["Connect the React interface to the Express/PostgreSQL API","List, create, edit and delete notices from the browser","Choose the guided, standard or extension track"]},"methods":["Lecture-demo","Differentiated three-track lab","Project-based learning (Campus Notices Board)","Peer review"],"resources":["React; Express; PostgreSQL; browser Developer Tools","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 15 materials","Meta Open Source (n.d.), React documentation","OpenJS Foundation (n.d.), Express documentation","Mozilla Developer Network (n.d.), CORS guide"],"assessment":["Quiz 10: proxy, CORS and request lifecycle","Lab 15 output: Campus Notices Board (chosen track)","Peer review rubric"],"sdg":[{"goal":"SDG 16: Peace, Justice and Strong Institutions","target":"Target 16.10: Ensure public access to information and protect fundamental freedoms, in accordance with national legislation and international agreements.","link":"A notices board gives students and staff open access to campus information."},{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Integrating a complete stack is the defining full-stack developer skill."}]}},{"week":16,"title":"Authentication and authorization basics","focus":"add login to the Notices Board","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Add registration and login to your Notices Board so that only logged-in users can post, and only admins can delete.",false]],[["Deliverable. ",true],["A working app with register, login and logout, a protected POST route, an admin-only DELETE route, and a Postman collection that proves each rule.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: login, protected routes and roles","tag":null,"kind":"divider","sub":"Build the server side first (Steps 1 to 6) and test it fully in Postman.","id":"step-by-step-guide-login-protected-routes-and-ro"},{"title":"Install and configure","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"npm install bcryptjs jsonwebtoken","lang":"bash"},{"k":"callout","t":"Add a long random secret to .env (never commit it). You can generate one with node -e \"console.log(require('crypto').randomBytes(32).toString('hex'))\"."},{"k":"code","t":"# .env\nJWT_SECRET=paste-the-long-random-string-here","lang":"javascript"}],"id":"install-and-configure"},{"title":"Create the users table","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Save this as db/auth.sql and run it with psql -U postgres -d campus_notices -f db/auth.sql:",false]]]},{"k":"code","t":"CREATE TABLE IF NOT EXISTS users (\n  id            SERIAL PRIMARY KEY,\n  name          TEXT NOT NULL,\n  email         TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  role          TEXT NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'admin')),\n  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()\n);","lang":"javascript"},{"k":"code","t":"\nALTER TABLE notices ADD COLUMN IF NOT EXISTS author_id INTEGER REFERENCES users(id);","lang":"javascript"},{"k":"callout","t":"Run \\d users in psql. You should see the five columns and a UNIQUE index on email. UNIQUE is what stops two accounts sharing an email, even if two people register at the same instant."}],"id":"create-the-users-table"},{"title":"Write the user model and the register and login controllers","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"// models/User.js\nconst db = require(\"../db\");\n\nexports.findByEmail = async (email) => {\n  const { rows } = await db.query(\"SELECT * FROM users WHERE email = $1\", [email.toLowerCase()]);\n  return rows[0]; // undefined when there is no such user\n};\n\nexports.create = async ({ name, email, passwordHash }) => {\n  const { rows } = await db.query(\n    `INSERT INTO users (name, email, password_hash)\n     VALUES ($1, $2, $3)\n     RETURNING id, name, email, role`,","lang":"javascript"},{"k":"code","t":"    [name, email.toLowerCase(), passwordHash]\n  );\n  return rows[0];\n};","lang":"javascript"},{"k":"code","t":"// controllers/authController.js\nconst bcrypt = require(\"bcryptjs\");\nconst jwt = require(\"jsonwebtoken\");\nconst User = require(\"../models/User\");\nconst asyncHandler = require(\"../middleware/asyncHandler\");\n\nconst signToken = (user) =>","lang":"javascript"},{"k":"code","t":"  jwt.sign({ sub: user.id, role: user.role }, process.env.JWT_SECRET, { expiresIn: \"2h\" });\n\nconst publicUser = ({ id, name, email, role }) => ({ id, name, email, role });\n\nexports.register = asyncHandler(async (req, res) => {\n  const { name, email, password } = req.body;\n  if (!name || !email || !password || password.length < 8) {\n    return res.status(400).json({ error: \"Name, email and a password of 8 or more characters are required.\" });\n  }\n  if (await User.findByEmail(email)) {","lang":"javascript"},{"k":"code","t":"    return res.status(409).json({ error: \"That email is already registered.\" });\n  }\n  const passwordHash = await bcrypt.hash(password, 10);\n  const user = await User.create({ name, email, passwordHash });\n  res.status(201).json({ token: signToken(user), user: publicUser(user) });\n});\n\nexports.login = asyncHandler(async (req, res) => {\n  const { email, password } = req.body;\n  const user = email && (await User.findByEmail(email));\n  const ok = user && password && (await bcrypt.compare(password, user.password_hash));","lang":"javascript"},{"k":"code","t":"  if (!ok) {\n    return res.status(401).json({ error: \"Invalid email or password.\" });\n  }\n  res.json({ token: signToken(user), user: publicUser(user) });\n});","lang":"javascript"},{"k":"callout","t":"Create routes/auth.js with router.post(\"/register\", register) and router.post(\"/login\", login), and in app.js add app.use(\"/api/auth\", authRoutes); above the 404 handler."},{"k":"list","items":[[["Postman check:",false]]]},{"k":"list","items":[[["POST /api/auth/register with name, email and an 8-character password returns 201 with a token and a user that has no password_hash.",false]],[["Run SELECT email, password_hash FROM users; in psql: the hash must look like $2a$10$..., never the real password.",false]]]}],"id":"write-the-user-model-and-the-register-and-login-"},{"title":"Write requireAuth and requireRole","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"// middleware/auth.js\nconst jwt = require(\"jsonwebtoken\");\n\nexports.requireAuth = (req, res, next) => {\n  const [type, token] = (req.headers.authorization || \"\").split(\" \");\n  if (type !== \"Bearer\" || !token) {\n    return res.status(401).json({ error: \"Please log in.\" });\n  }\n  try {\n    const payload = jwt.verify(token, process.env.JWT_SECRET);\n    req.user = { id: payload.sub, role: payload.role };\n    next();\n  } catch {","lang":"javascript"},{"k":"code","t":"    res.status(401).json({ error: \"Your session is invalid or has expired.\" });\n  }\n};\n\nexports.requireRole = (role) => (req, res, next) =>\n  req.user && req.user.role === role\n    ? next()\n    : res.status(403).json({ error: \"You are not allowed to do that.\" });","lang":"javascript"}],"id":"write-requireauth-and-requirerole"},{"title":"Protect the routes","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In routes/notices.js:",false]]]},{"k":"code","t":"const { requireAuth, requireRole } = require(\"../middleware/auth\");\n\nrouter.get(\"/\", c.getNotices);                                        // public\nrouter.post(\"/\", requireAuth, c.createNotice);                        // any logged-in user\nrouter.delete(\"/:id\", requireAuth, requireRole(\"admin\"), c.deleteNotice); // admin only","lang":"javascript"},{"k":"callout","t":"Also save the author: in createNotice add author_id as a fourth column with req.user.id as the fourth parameter, in the same parameterized INSERT. The foreign key refuses an id that does not exist in users."}],"id":"protect-the-routes"},{"title":"Test every rule in Postman","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["In Postman choose the Authorization tab, type Bearer Token, and paste the token from login.",false]],[["To test the admin rule, make yourself an admin in psql:",false]]]},{"k":"table","head":["Request","Expected"],"rows":[["POST /api/notices with no token","401"],["POST /api/notices with a bad token (change a character)","401"],["POST /api/notices as a student","201"],["DELETE /api/notices/1 as a student","403"],["DELETE /api/notices/1 as an admin","204"],["POST /api/auth/login with a wrong password","401, same message as an unknown email"],["POST /api/auth/register with an email already used","409"]]},{"k":"list","items":[[["Save these requests in your Postman collection.",false]]]}],"extra":["UPDATE users SET role = 'admin' WHERE email = 'you@example.com';, then log in again to get a new token (the role is inside the token, so an old token still says student)."],"id":"test-every-rule-in-postman"},{"title":"Build the login and register forms","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Create AuthForm.jsx with email, password and (for register) name inputs as controlled inputs, a mode prop (\"login\" or \"register\") and an onAuth prop.",false]],[["On submit, send a POST to \"/api/auth/\" + mode with the header Content-Type: application/json and the body JSON.stringify(values).",false]]]}],"extra":["Check res.ok, and show data.error if it fails. On success, call onAuth(data)."],"id":"build-the-login-and-register-forms"},{"title":"Keep the token","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["In App.jsx:",false]]]},{"k":"code","t":"const [token, setToken] = useState(() => localStorage.getItem(\"token\"));\n\nfunction handleLogin({ token }) {\n  localStorage.setItem(\"token\", token);\n  setToken(token);\n}\nfunction handleLogout() {\n  localStorage.removeItem(\"token\");\n  setToken(null);\n}","lang":"javascript"},{"k":"callout","t":"Show <AuthForm onAuth={handleLogin} mode=\"login\" /> when token is null, and a Logout button when it is set. Log in, refresh the page, and you should stay logged in."}],"id":"keep-the-token"},{"title":"Send the token and hide the form","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["Show NoticeForm only when token exists.",false]],[["In the POST request add the header Authorization with the value \"Bearer \" + token, and if the response status is 401 call handleLogout().",false]]]}],"extra":["log out and the post form disappears; log in, post a notice, and see it in the list. Open the Network tab and confirm the request has the Authorization header. Remember that hiding the form is only convenience: Step 6 proved the real protection is on the server."],"id":"send-the-token-and-hide-the-form"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["Passwords are stored as hashes, and no response contains password_hash.",false]],[["The Postman table above passes, including 401 versus 403.",false]],[["You stay logged in after a refresh, and logout works.",false]],[["You can explain the difference between 401 and 403 and why the role check must be on the server.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Make notices deletable by their author as well as by admins. Then write a short comparison, with one paragraph each, of localStorage and httpOnly cookies for storing a token. Name one attack each approach is more exposed to."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_16_Laboratory_Authentication_and_authorization_basics.pptx","slideCount":24,"pptx":"downloads/laboratory/Week_16_Laboratory_Authentication_and_authorization_basics.pptx","syllabus":{"label":"Week 16","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Distinguish authentication from authorization.","Store passwords securely using hashing.","Implement login and protect routes with middleware.","Identify common web security risks using the OWASP Top Ten."],"topics":{"lecture":["Password hashing","Sessions versus tokens (JWT)","Protected routes and role-based access","Users table in PostgreSQL","OWASP Top Ten overview"],"laboratory":["Create the users table and register users with hashed passwords","Implement login and token verification middleware","Restrict posting to signed-in users"]},"methods":["Lecture with security demo","Threat-modelling discussion","Hands-on lab practice","Peer code review"],"resources":["Express; PostgreSQL; bcrypt; JSON Web Tokens; Postman","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 16 materials","OWASP Foundation (2021), OWASP Top Ten","OpenJS Foundation (n.d.), Express documentation"],"assessment":["Lab 16 output: login on the Notices Board","Project Checkpoint 4: authenticated Notices Board","Quiz 11: authentication and security basics"],"sdg":[{"goal":"SDG 16: Peace, Justice and Strong Institutions","target":"Target 16.10: Ensure public access to information and protect fundamental freedoms, in accordance with national legislation and international agreements.","link":"Protecting accounts and personal data protects the freedoms and privacy of system users."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.b: Support domestic technology development, research and innovation.","link":"Secure software is essential to trustworthy digital infrastructure."}]}},{"week":17,"title":"Testing, environment variables and deployment","focus":"test and deploy the Notices Board","duration":"3 hours","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Add automated tests to your Notices Board, move its configuration into environment variables, and put it on the internet.",false]],[["Deliverable. ",true],["At least five passing tests, a .env.example, a production build served by Express, and a live URL (or, if hosting is unavailable, a screenshot of the production build running locally).",false]]]}],"extra":["If your deployed site shows a blank page, open the browser console and the Network tab first. The first red error nearly always names the problem."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: test and deploy","tag":null,"kind":"divider","sub":"Do the tests first (Steps 1 to 4), then configuration (Step 5), then the production build (Step 6), and deploy last (Steps 7 and 8).","id":"step-by-step-guide-test-and-deploy"},{"title":"Install the tools and make a test database","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"npm install --save-dev jest supertest\ncreatedb -U postgres campus_notices_test\npsql -U postgres -d campus_notices_test -f db/schema.sql\npsql -U postgres -d campus_notices_test -f db/auth.sql","lang":"bash"},{"k":"callout","t":"In package.json set \"test\": \"jest --runInBand\". Add the test database address to .env:"},{"k":"code","t":"DATABASE_TEST_URL=postgres://postgres:yourpassword@localhost:5432/campus_notices_test","lang":"bash"},{"k":"callout","t":"Use the same psql commands for every schema file you have created. You should be able to run psql -U postgres -d campus_notices_test -c \"\\dt\" and see notices and users."}],"id":"install-the-tools-and-make-a-test-database"},{"title":"Teach db.js to choose the right database","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Jest sets NODE_ENV to test by itself.",false]]]},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst { Pool } = require(\"pg\");\n\nconst isTest = process.env.NODE_ENV === \"test\";\nconst pool = new Pool({\n  connectionString: isTest ? process.env.DATABASE_TEST_URL : process.env.DATABASE_URL,\n  ssl: process.env.NODE_ENV === \"production\" ? { rejectUnauthorized: false } : false,\n});","lang":"javascript"},{"k":"code","t":"\nmodule.exports = {\n  query: (text, params) => pool.query(text, params),\n  pool,\n};","lang":"javascript"},{"k":"callout","t":"Confirm that app.js exports the app and only server.js calls listen. Supertest needs that split."}],"id":"teach-db-js-to-choose-the-right-database"},{"title":"Write the tests","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Create tests/notices.test.js:",false]]]},{"k":"code","t":"const request = require(\"supertest\");\nconst app = require(\"../app\");\nconst db = require(\"../db\");\n\nlet token;\n\nbeforeEach(async () => {\n  await db.query(\"TRUNCATE notices, users RESTART IDENTITY CASCADE\");\n  const body = { name: \"Test\", email: \"test@example.com\", password: \"password123\" };\n  const res = await request(app).post(\"/api/auth/register\").send(body);","lang":"javascript"},{"k":"code","t":"  token = res.body.token;\n});\n\nafterAll(async () => {\n  await db.pool.end(); // lets Jest exit cleanly\n});\n\ndescribe(\"POST /api/notices\", () => {\n  test(\"creates a notice and returns 201\", async () => {\n    const res = await request(app)\n      .post(\"/api/notices\")\n      .set(\"Authorization\", `Bearer ${token}`)\n      .send({ title: \"Hello\", message: \"World\" });\n    expect(res.status).toBe(201);","lang":"javascript"},{"k":"code","t":"    expect(res.body.title).toBe(\"Hello\");\n  });\n\n  test(\"rejects an empty title with 400\", async () => {\n    const res = await request(app)\n      .post(\"/api/notices\")\n      .set(\"Authorization\", `Bearer ${token}`)\n      .send({ title: \"\", message: \"World\" });\n    expect(res.status).toBe(400);\n    expect(res.body.error).toBeDefined();\n  });\n\n  test(\"rejects a request with no token with 401\", async () => {","lang":"javascript"},{"k":"code","t":"    const res = await request(app).post(\"/api/notices\").send({ title: \"Hi\", message: \"There\" });\n    expect(res.status).toBe(401);\n  });\n});\n\ndescribe(\"GET /api/notices\", () => {\n  test(\"returns the list\", async () => {\n    await request(app).post(\"/api/notices\").set(\"Authorization\", `Bearer ${token}`).send({ title: \"A\", message: \"B\" });\n    const res = await request(app).get(\"/api/notices\");\n    expect(res.status).toBe(200);\n    expect(res.body).toHaveLength(1);\n  });","lang":"javascript"},{"k":"code","t":"});\n\ndescribe(\"DELETE /api/notices/:id\", () => {\n  test(\"a student cannot delete (403)\", async () => {\n    const created = await request(app).post(\"/api/notices\").set(\"Authorization\", `Bearer ${token}`).send({ title: \"A\", message: \"B\" });\n    const res = await request(app).delete(`/api/notices/${created.body.id}`).set(\"Authorization\", `Bearer ${token}`);\n    expect(res.status).toBe(403);\n  });\n});","lang":"javascript"}],"id":"write-the-tests"},{"title":"Run the tests, then break something","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Run npm test.",false]],[["You should see five passing tests.",false]],[["Now change the 400 check in your controller to return 200, run again, and read the failing test output: it names the test, the expected value and the received value.",false]]]}],"extra":["Undo the change and see all tests pass. If Jest says \"did not exit\", you forgot pool.end(). If your tests touch real notices, NODE_ENV is not test: check the isTest line."],"id":"run-the-tests-then-break-something"},{"title":"Move every setting into environment variables","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Search your code for anything that differs between your laptop and a live server: the port (process.env.PORT || 3001), the database address, JWT_SECRET, and the allowed website in CORS (process.env.CLIENT_URL).",false]],[["Then write .env.example with fake values and commit it.",false]],[["Confirm .env is ignored by Git:",false]]]},{"k":"code","t":"# .env.example\nPORT=3001\nDATABASE_URL=postgres://user:password@localhost:5432/campus_notices\nDATABASE_TEST_URL=postgres://user:password@localhost:5432/campus_notices_test\nJWT_SECRET=change-me-to-a-long-random-string\nCLIENT_URL=http://localhost:5173","lang":"javascript"},{"k":"callout","t":"Run git status. .env must not appear in the list."}],"id":"move-every-setting-into-environment-variables"},{"title":"Build the client and serve it from Express","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"cd client\nnpm run build","lang":"bash"},{"k":"list","items":[[["You should see a dist folder.",false]],[["In app.js, above the 404 handler, add the production block from the lecture so Express serves dist and returns index.html for other routes.",false]],[["Run the server with NODE_ENV=production node server.js and open http://localhost:3001.",false]]]}],"extra":["The whole app should work from one address with no Vite running. Take this screenshot: it is your fallback if deployment fails."],"id":"build-the-client-and-serve-it-from-express"},{"title":"Push to GitHub and deploy","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Make sure .gitignore contains node_modules, .env and dist.",false]],[["Then:",false]]]},{"k":"code","t":"git add .\ngit commit -m \"Notices Board ready for deployment\"\ngit push","lang":"bash"},{"k":"list","items":[[["On your host, create a new web service from the repository, set the build command and start command from your root package.json, and add each variable from .env.example (with real values) in the host's dashboard.",false]]]}],"extra":["Create a hosted PostgreSQL database, run db/schema.sql and db/auth.sql on it, and put its connection string in DATABASE_URL."],"id":"push-to-github-and-deploy"},{"title":"Test the live site","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Open the live address with the Network tab open.",false]],[["Go through every feature: list, register, login, post, delete as admin, logout.",false]],[["Add a GET /api/health route and open it to confirm the app is alive.",false]]]}],"extra":["Write down anything that fails. A blank page almost always has a red error in the Console that names the cause. A free host may take up to a minute to wake up on the first request."],"id":"test-the-live-site"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["npm test shows at least five passing tests, and you have seen one fail on purpose.",false]],[[".env.example exists, and .env is not in Git.",false]],[["The production build works locally from Express at one address.",false]],[["You have a live URL (or the local production screenshot) and a list of any problems.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a GitHub Actions workflow that runs your tests on every push. It needs to start a PostgreSQL service (a services: postgres block), create the tables from your schema files, install dependencies, and run npm test. Add the build status badge to your README."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_17_Laboratory_Testing_environment_variables_and_deploy.pptx","slideCount":21,"pptx":"downloads/laboratory/Week_17_Laboratory_Testing_environment_variables_and_deploy.pptx","syllabus":{"label":"Week 17","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Write automated tests for API endpoints.","Manage configuration and secrets with environment variables.","Deploy a full-stack application to a hosting platform.","Prepare a deployed project for demonstration."],"topics":{"lecture":["Automated testing of API endpoints","Environment variables and secrets management","Hosted PostgreSQL and deployment","Pre-deployment checklist"],"laboratory":["Write automated tests for the API","Move configuration to environment variables","Deploy the Campus Notices Board with a hosted PostgreSQL database"]},"methods":["Lecture with deployment walkthrough","Lab sprint","Dry-run demo","Peer feedback"],"resources":["Git/GitHub; free-tier hosting platform and hosted PostgreSQL; Postman","Limson, H. D. (2026), CSAE 104 Web programming course site: Week 17 materials","OpenJS Foundation (n.d.), Node.js documentation","OWASP Foundation (2021), OWASP Top Ten (secrets and configuration)"],"assessment":["Lab 17 output: tested and deployed Notices Board","Dry-run demo checklist","Project Checkpoint 5: deployed application URL"],"sdg":[{"goal":"SDG 8: Decent Work and Economic Growth","target":"Target 8.2: Achieve higher levels of economic productivity through diversification, technological upgrading and innovation.","link":"Deploying working applications is the step from classroom project to real product, service and entrepreneurship."},{"goal":"SDG 17: Partnerships for the Goals","target":"Target 17.8: Enhance the use of enabling technology, in particular information and communications technology.","link":"Cloud hosting and open-source tools enable ICT-based solutions to reach users."}]}},{"week":18,"title":"Final project presentations and demos","focus":"demos","duration":"3 hours","sections":[{"title":"Overview","tag":"LAB","kind":"brief","blocks":[{"k":"list","items":[[["Use the lab for the remaining presentations, for peer feedback, and for a final round of questions.",false]],[["While one team presents, everyone else completes a peer feedback form.",false]]]},{"k":"table","head":["Peer feedback question","Scale"],"rows":[["The problem and users were clearly explained","1 to 5"],["The demo worked and showed the main journey","1 to 5"],["The team could explain how it works underneath","1 to 5"],["One thing that impressed me","A sentence"],["One thing I would improve","A sentence"]]}],"id":"overview"},{"title":"How your project is assessed (100 points)","tag":"LAB","kind":"brief","blocks":[{"k":"table","head":["Criterion","Points","What the instructor looks for"],"rows":[["Problem and scope","10","A real problem, a sensible scope, and clear users"],["Technical depth","25","A sound PERN design: REST routes, a well-chosen table design (keys, constraints, foreign keys), authentication and authorization, validation"],["Working product and demo","25","The core journey works live, errors are handled, and the interface is usable"],["Code quality and security habits","15","Clear structure, no secrets in the repository, passwords hashed, input validated"],["Testing and deployment","10","Automated tests that pass, and a live or reproducible deployment"],["Presentation and teamwork","10","Clear, well-timed, and everybody contributes"],["Individual understanding","5","Each member answers a question about the code"],["Total","100",""]]},{"k":"list","items":[[["Your instructor may adjust marks for individual contribution after reading the repository history and the peer feedback.",false]]]}],"id":"how-your-project-is-assessed-100-points"},{"title":"Step-by-step guide: demo day","tag":null,"kind":"divider","sub":"This lab is for presenting and learning from each other.","id":"step-by-step-guide-demo-day"},{"title":"One day before: freeze and rehearse","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Stop adding features.",false]],[["Fix only bugs that break the main journey.",false]],[["Run npm test, then open the live site (or your local production build) and walk through your demo from a fresh browser window with no one logged in.",false]]]}],"id":"one-day-before-freeze-and-rehearse"},{"title":"Prepare your demo","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Write the five-minute script on paper: the problem in one sentence, the main user journey (three to five clicks), one error case you handle on purpose, and one thing you would build next.",false]],[["Decide who speaks for each part so everyone contributes.",false]]]}],"extra":["Have a backup ready (screenshots or a short screen recording) in case the network fails."],"id":"prepare-your-demo"},{"title":"Prepare to explain what is underneath","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Each member must be able to answer a question about the code.",false]],[["Practise answering these aloud:",false]],[["What happens, step by step, when a user posts a notice?",false]]]}],"extra":["Where is the password checked, and how is it stored? Which rule of your table design stops bad data? What would break if the token were missing?"],"id":"prepare-to-explain-what-is-underneath"},{"title":"Demo order checklist","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Before you present:",false]],[["Database seeded with a few realistic notices and at least one admin user.",false]],[["Server running and GET /api/health returns 200.",false]],[["Browser zoomed so the back row can read it, with the Network tab ready.",false]],[["Repository open on a second tab, in case someone asks to see code.",false]]]}],"id":"demo-order-checklist"},{"title":"While another team presents","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Complete the peer feedback form below for every team.",false]],[["Score honestly, and write one specific thing that impressed you and one specific improvement.",false]],[["A sentence like \"the empty state was clear\" is more useful than \"good job\".",false]]]}],"id":"while-another-team-presents"},{"title":"After your own demo","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Write down every question you were asked and whether you could answer it.",false]],[["Read your peer feedback.",false]],[["Pick one improvement and note how you would make it.",false]]]}],"id":"after-your-own-demo"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["You presented a working demo within the time limit, and every member spoke.",false]],[["You completed a peer feedback form for every other team.",false]],[["Your repository has no secrets, and its README explains how to run it.",false]],[["You have written down your one next improvement.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Write a one-page post-mortem of your project. Describe what went well, the hardest bug and how you found it, one decision you would reverse, and one thing you learned about working as a team."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"file":"Week_18_Laboratory_Final_project_presentations_and_demos.pptx","slideCount":13,"pptx":"downloads/laboratory/Week_18_Laboratory_Final_project_presentations_and_demos.pptx","syllabus":{"label":"Week 18","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Demonstrate comprehensive mastery of web programming topics across the MERN and PERN halves of the course.","Present and defend the complete, deployed Campus Notices Board.","Justify design choices (stack, database, security) in the project."],"topics":{"lecture":["Final Examination","Written component: comprehensive theory, Weeks 1-17 topics"],"laboratory":["Final Lab Exam / Campus Notices Board Presentation","Practical component: build a feature in the full-stack stack","Campus Notices Board presentation: demo and defense of the deployed application"]},"methods":["Written examination","Practical / coding examination","Project presentation, demo and defense","Peer feedback"],"resources":["VS Code; Node.js; React; PostgreSQL","Limson, H. D. (2026), CSAE 104 Web programming course site: all course materials (Weeks 1-17)","Mozilla Developer Network (n.d.); Meta Open Source (n.d.); OpenJS Foundation (n.d.); PostgreSQL Global Development Group (n.d.)","Campus Notices Board repository and deployed site"],"assessment":["Final Written Exam (40% of final term grade)","Final Practical Exam (part of 60% class standing)","Campus Notices Board presentation graded per code rubric: Functionality, Code Efficiency, Code Organization, Use of Web Technologies, Code Readability, Error Handling, Innovation and Creativity, Alignment with SDGs","Final Grade = 40% Midterm + 60% Final Term Grade"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"The project and final exam assess cumulative mastery of skills that qualify students for entry-level web development roles."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"The capstone demonstrates the ability to design, build and deploy a functional data-driven system."}]}}];